def check(part):
    import math

    edge = 5.0

    # Retain only pores subject to the criterion.
    points = [
        tuple(pore["centroid"])
        for pore in part["pores"]
        if pore["d_eq_mm"] >= 0.10
    ]

    if len(points) <= 4:
        return True

    # Divide space into half-open 5 mm grid cells. Any five points in one
    # cell necessarily fit within a closed 5 mm cube.
    cells = {}
    for point in points:
        cell = tuple(math.floor(coordinate / edge) for coordinate in point)
        cells.setdefault(cell, []).append(point)
        if len(cells[cell]) >= 5:
            return False

    def contains_five_in_cube(candidate_points):
        """Return True if five candidates fit in some closed 5 mm cube."""
        by_x = sorted(candidate_points, key=lambda p: p[0])

        for i, point in enumerate(by_x):
            x0 = point[0]
            if i > 0 and by_x[i - 1][0] == x0:
                continue

            x_window = [
                p for p in by_x
                if x0 <= p[0] <= x0 + edge
            ]
            if len(x_window) < 5:
                continue

            by_y = sorted(x_window, key=lambda p: p[1])
            for j, y_point in enumerate(by_y):
                y0 = y_point[1]
                if j > 0 and by_y[j - 1][1] == y0:
                    continue

                z_values = sorted(
                    p[2] for p in by_y
                    if y0 <= p[1] <= y0 + edge
                )

                for k in range(len(z_values) - 4):
                    if z_values[k + 4] - z_values[k] <= edge:
                        return True

        return False

    # Every 5 mm cube intersects at most two adjacent grid cells along each
    # axis, so it is contained in one of these 2x2x2 cell blocks.
    blocks = set()
    for cx, cy, cz in cells:
        for dx in (-1, 0):
            for dy in (-1, 0):
                for dz in (-1, 0):
                    blocks.add((cx + dx, cy + dy, cz + dz))

    for bx, by, bz in blocks:
        candidates = []
        for dx in (0, 1):
            for dy in (0, 1):
                for dz in (0, 1):
                    candidates.extend(
                        cells.get((bx + dx, by + dy, bz + dz), ())
                    )

        if len(candidates) >= 5 and contains_five_in_cube(candidates):
            return False

    return True
```

ASSUMPTIONS:
- Every pore is considered regardless of inspection zones, wall thickness, surface distance, shape, or other fields not named in the criterion.
- Cubes may be positioned anywhere and are not required to lie inside the part or an inspection zone.
- Cube axes coincide with the coordinate axes used by the pore centroids.
- Pores with `d_eq_mm` exactly equal to `0.10` are included.
- Cube boundaries are closed, so coordinate spans exactly equal to `5.0` mm are accepted as being inside one cube.
- Each pore record counts separately, including records with identical centroids.
- Numeric inputs are finite, valid, and expressed in a common coordinate system.
- Floating-point comparisons are performed directly without an additional tolerance.

```python
def check(part):
    edge = 5.0

    points = sorted(
        (
            tuple(pore["centroid"])
            for pore in part["pores"]
            if pore["d_eq_mm"] >= 0.10
        ),
        key=lambda point: point[0],
    )

    if len(points) < 5:
        return True

    x_start = 0
    while x_start < len(points):
        x_min = points[x_start][0]

        x_end = x_start
        while x_end < len(points) and points[x_end][0] <= x_min + edge:
            x_end += 1

        x_slab = sorted(points[x_start:x_end], key=lambda point: point[1])

        y_start = 0
        while y_start < len(x_slab):
            y_min = x_slab[y_start][1]

            y_end = y_start
            while y_end < len(x_slab) and x_slab[y_end][1] <= y_min + edge:
                y_end += 1

            if y_end - y_start >= 5:
                z_values = sorted(
                    point[2] for point in x_slab[y_start:y_end]
                )

                for i in range(len(z_values) - 4):
                    if z_values[i + 4] - z_values[i] <= edge:
                        return False

            while (
                y_start < len(x_slab)
                and x_slab[y_start][1] == y_min
            ):
                y_start += 1

        while (
            x_start < len(points)
            and points[x_start][0] == x_min
        ):
            x_start += 1

    return True
```

