def check(part):
    from math import dist

    relevant_pores = [
        pore for pore in part["pores"]
        if pore["d_eq_mm"] >= 0.20
    ]

    for i, pore_a in enumerate(relevant_pores):
        for pore_b in relevant_pores[i + 1:]:
            minimum_separation = 3.0 * max(
                pore_a["d_eq_mm"],
                pore_b["d_eq_mm"]
            )
            actual_separation = dist(
                pore_a["centroid"],
                pore_b["centroid"]
            )

            if actual_separation < minimum_separation:
                return False

    return True
