def check(part):
    """
    A pore is counted in a reference volume when its centroid lies within it.
    Reference volumes are treated as any axis-aligned 5 mm cube, with boundary
    points included.
    """
    size = 5.0
    points = sorted(
        (pore["centroid"][0], pore["centroid"][1], pore["centroid"][2])
        for pore in part["pores"]
        if pore["d_eq_mm"] >= 0.15
    )

    if len(points) <= 3:
        return True

    # A violation exists if four qualifying centroids have coordinate spans
    # no greater than 5 mm in x, y, and z.
    for i, (x_min, _, _) in enumerate(points):
        x_window = []
        for point in points[i:]:
            if point[0] > x_min + size:
                break
            x_window.append(point)

        if len(x_window) < 4:
            continue

        x_window.sort(key=lambda point: point[1])

        for j, (_, y_min, _) in enumerate(x_window):
            z_values = []
            for point in x_window[j:]:
                if point[1] > y_min + size:
                    break
                z_values.append(point[2])

            if len(z_values) < 4:
                continue

            z_values.sort()
            for k in range(len(z_values) - 3):
                if z_values[k + 3] - z_values[k] <= size:
                    return False

    return True
