    def bbox_distance_squared(a, b):
        dx = max(0.0, a[0] - b[1], b[0] - a[1])
        dy = max(0.0, a[2] - b[3], b[2] - a[3])
        dz = max(0.0, a[4] - b[5], b[4] - a[5])
        return dx * dx + dy * dy + dz * dz

    for i, pore_a in enumerate(relevant):
        for pore_b in relevant[i + 1:]:
            if bbox_distance_squared(pore_a["bbox"], pore_b["bbox"]) < 1.0:
