from collections import defaultdict
import math
from operator import itemgetter


def check(part):
    edge = 5.0
    min_d_eq = 0.10
    max_pores = 4
    needed = max_pores + 1
    cell_size = 6.0  # > edge so any 5.0 mm interval spans at most 2 cells

    points = [
        (p["centroid"][0], p["centroid"][1], p["centroid"][2])
        for p in part["pores"]
        if p["d_eq_mm"] >= min_d_eq
    ]

    if len(points) < needed:
        return True

    get_x = itemgetter(0)
    get_y = itemgetter(1)

    def has_dense_cube(pts):
        n = len(pts)
        if n < needed:
            return False

        pts_x = sorted(pts, key=get_x)
        j = 0
        prev_j = 0
        for i in range(n - needed + 1):
            x_limit = pts_x[i][0] + edge
            while j < n and pts_x[j][0] <= x_limit:
                j += 1
            if j > prev_j:
                prev_j = j
                if j - i >= needed:
                    wx = sorted(pts_x[i:j], key=get_y)
                    m = len(wx)
                    yj = 0
                    prev_yj = 0
                    for yi in range(m - needed + 1):
                        y_limit = wx[yi][1] + edge
                        while yj < m and wx[yj][1] <= y_limit:
                            yj += 1
                        if yj > prev_yj:
                            prev_yj = yj
                            if yj - yi >= needed:
                                zs = sorted(p[2] for p in wx[yi:yj])
                                for k in range(len(zs) - needed + 1):
                                    if zs[k + max_pores] <= zs[k] + edge:
                                        return True
                        if yj == m:
                            break
            if j == n:
                break
        return False

    # Bucket qualifying centroids into 6.0 mm grid cells.
    cells = defaultdict(list)
    for pt in points:
        key = (
            math.floor(pt[0] / cell_size),
            math.floor(pt[1] / cell_size),
            math.floor(pt[2] / cell_size),
        )
        cells[key].append(pt)

    # A 6.0 mm cell is covered by 2x2x2 = 8 cubes of 5.0 mm (at most 32 pores if accepted).
    max_per_cell = 8 * max_pores
    for cell_pts in cells.values():
        c = len(cell_pts)
        if c > max_per_cell:
            return False
        if c >= needed and has_dense_cube(cell_pts):
            return False

    # Every 5.0 mm cube fits inside a 2x2x2 block of 6.0 mm cells.
    block_counts = defaultdict(int)
    for (cx, cy, cz), cell_pts in cells.items():
        c = len(cell_pts)
        for dx in (0, 1):
            ox = cx - dx
            for dy in (0, 1):
                oy = cy - dy
                for dz in (0, 1):
                    block_counts[(ox, oy, cz - dz)] += c

    # A 12.0 mm block is covered by 3x3x3 = 27 cubes of 5.0 mm (at most 108 pores if accepted).
    max_per_block = 27 * max_pores
    for (ox, oy, oz), total in block_counts.items():
        if total < needed:
            continue
        if total > max_per_block:
            return False

        block_pts = []
        num_cells = 0
        has_x0 = False
        has_y0 = False
        has_z0 = False
        for dx in (0, 1):
            nx = ox + dx
            for dy in (0, 1):
                ny = oy + dy
                for dz in (0, 1):
                    cell_pts = cells.get((nx, ny, oz + dz))
                    if cell_pts is not None:
                        num_cells += 1
                        if dx == 0:
                            has_x0 = True
                        if dy == 0:
                            has_y0 = True
                        if dz == 0:
                            has_z0 = True
                        block_pts.extend(cell_pts)

        if num_cells >= 2 and has_x0 and has_y0 and has_z0:
            if has_dense_cube(block_pts):
                return False

    return True
```

ASSUMPTIONS:
The criterion applies globally across all pores in `part["pores"]` regardless of `part["zones"]`, and cubes at any continuous 3D position are considered even if a cube extends outside the part boundary.
Qualifying pores are selected by exact floating-point comparison `pore["d_eq_mm"] >= 0.10` with no numerical tolerance.
Closed-cube membership (faces, edges, and vertices included) is evaluated using exact floating-point comparison (`coord <= min_coord + 5.0`) with no numerical tolerance.
Each entry in `part["pores"]` meeting the diameter threshold is counted individually even if multiple pores have identical centroid coordinates.
Only `centroid` and `d_eq_mm` are used; pore bounding boxes and other pore or part attributes do not affect acceptance.

```python
import math


def check(part):
    edge = 5.0
    min_d_eq = 0.10
    max_pores = 4

    def has_dense_cube(points):
        points.sort(key=lambda p: p[0])
        n = len(points)
        right = 0
        prev_right = -1
        for left in range(n):
            x_min = points[left][0]
            while right < n and points[right][0] - x_min <= edge:
                right += 1
            if right == prev_right:
                continue
            prev_right = right
            if right - left <= max_pores:
                continue

            y_pts = sorted(points[left:right], key=lambda p: p[1])
            m = len(y_pts)
            yr = 0
            prev_yr = -1
            for yl in range(m):
                y_min = y_pts[yl][1]
                while yr < m and y_pts[yr][1] - y_min <= edge:
                    yr += 1
                if yr == prev_yr:
                    continue
                prev_yr = yr
                if yr - yl <= max_pores:
                    continue

                zs = sorted(p[2] for p in y_pts[yl:yr])
                for k in range(len(zs) - max_pores):
                    if zs[k + max_pores] - zs[k] <= edge:
                        return True
        return False

    grid = {}
    for pore in part["pores"]:
        if pore["d_eq_mm"] < min_d_eq:
            continue
        x, y, z = pore["centroid"]
        cell = (
            math.floor(x / edge),
            math.floor(y / edge),
            math.floor(z / edge),
        )
        bucket = grid.get(cell)
        if bucket is None:
            grid[cell] = [(x, y, z)]
        else:
            bucket.append((x, y, z))
            if len(bucket) > max_pores:
                return False

    candidate_blocks = set()
    for gx, gy, gz in grid:
        for dx in (0, 1):
            for dy in (0, 1):
                for dz in (0, 1):
                    candidate_blocks.add((gx - dx, gy - dy, gz - dz))

    for bx, by, bz in candidate_blocks:
        block_points = []
        for dx in (0, 1):
            for dy in (0, 1):
                for dz in (0, 1):
                    pts = grid.get((bx + dx, by + dy, bz + dz))
                    if pts:
                        block_points.extend(pts)
        if len(block_points) > max_pores and has_dense_cube(block_points):
            return False

    return True
