def check(part):
    CUBE_EDGE = 5.0
    MIN_D_EQ = 0.10
    MAX_PORES_IN_CUBE = 4

    points = [
        (p["centroid"][0], p["centroid"][1], p["centroid"][2])
        for p in part["pores"]
        if p["d_eq_mm"] >= MIN_D_EQ
    ]

    if len(points) <= MAX_PORES_IN_CUBE:
        return True

    # Spatial grid with cell_size > CUBE_EDGE so any two points within CUBE_EDGE
    # along an axis fall into the same or adjacent cells.
    cell_size = 5.5
    grid = {}
    for pt in points:
        key = (
            math.floor(pt[0] / cell_size),
            math.floor(pt[1] / cell_size),
            math.floor(pt[2] / cell_size),
        )
        bucket = grid.get(key)
        if bucket is None:
            grid[key] = [pt]
        else:
            bucket.append(pt)
            # A 5.5^3 cell splits into 8 octants of 2.75^3, each fitting inside a 5.0^3 cube.
            if len(bucket) == 8 * MAX_PORES_IN_CUBE + 1:
                mid_x = (key[0] + 0.5) * cell_size
                mid_y = (key[1] + 0.5) * cell_size
                mid_z = (key[2] + 0.5) * cell_size
                subcells = {}
                for q in bucket:
                    skey = (q[0] >= mid_x, q[1] >= mid_y, q[2] >= mid_z)
                    sb = subcells.get(skey)
                    if sb is None:
                        subcells[skey] = [q]
                    else:
                        sb.append(q)
                        if len(sb) > MAX_PORES_IN_CUBE:
                            xs = [r[0] for r in sb]
                            ys = [r[1] for r in sb]
                            zs = [r[2] for r in sb]
                            if (
                                max(xs) - min(xs) <= CUBE_EDGE
                                and max(ys) - min(ys) <= CUBE_EDGE
                                and max(zs) - min(zs) <= CUBE_EDGE
                            ):
                                return False

    for (gx, gy, gz), bucket in grid.items():
        nearby = []
        for dx in (0, 1):
            nx = gx + dx
            for dy in (-1, 0, 1):
                ny = gy + dy
                for dz in (-1, 0, 1):
                    nb = grid.get((nx, ny, gz + dz))
                    if nb is not None:
                        nearby.extend(nb)

        if len(nearby) <= MAX_PORES_IN_CUBE:
            continue

        for px, py, pz in bucket:
            yz = [
                (qy, qz)
                for qx, qy, qz in nearby
                if qx >= px
                and qx - px <= CUBE_EDGE
                and abs(qy - py) <= CUBE_EDGE
                and abs(qz - pz) <= CUBE_EDGE
            ]
            m = len(yz)
            if m <= MAX_PORES_IN_CUBE:
                continue

            yz.sort()
            right = 0
            for left in range(m - MAX_PORES_IN_CUBE):
                y_min = yz[left][0]
                while right < m and yz[right][0] - y_min <= CUBE_EDGE:
                    right += 1
                if right - left > MAX_PORES_IN_CUBE:
                    zs = sorted(yz[k][1] for k in range(left, right))
                    for i in range(len(zs) - MAX_PORES_IN_CUBE):
                        if zs[i + MAX_PORES_IN_CUBE] - zs[i] <= CUBE_EDGE:
                            return False
                if right == m:
                    break

    return True
```

ASSUMPTIONS:
- All pores in `part["pores"]` with `d_eq_mm >= 0.10` are included regardless of inspection zones or surface distance, since the criterion applies to cubes at any position without zone or surface exclusions.
- Cubes are treated as closed axis-aligned boxes (`[x0, x0 + 5.0] x [y0, y0 + 5.0] x [z0, z0 + 5.0]`), so centroids on cube faces, edges, or vertices count as inside.
- Distinct pore entries in `part["pores"]` are counted separately even if they have identical centroid coordinates.
- Standard IEEE 754 floating-point comparisons (`>= 0.10`, `<= 5.0`) are used without an additional numerical tolerance.

