from math import floor


def check(part):
    EDGE = 5.0
    TOL = 1e-12
    LIMIT = EDGE + TOL
    CELL = 5.01  # Strictly larger than LIMIT so any valid cube spans at most +/-1 cell per axis
    MIN_D_EQ = 0.10
    MAX_PORES = 4

    grid = {}
    qualifying_count = 0

    for pore in part["pores"]:
        if pore["d_eq_mm"] < MIN_D_EQ:
            continue
        x, y, z = pore["centroid"]
        key = (floor(x / CELL), floor(y / CELL), floor(z / CELL))
        cell = grid.get(key)
        if cell is None:
            grid[key] = [(x, y, z)]
        else:
            cell.append((x, y, z))
            # A 5.01 mm cell splits into 8 sub-cubes of side 2.505 mm <= 5.0 mm;
            # by pigeonhole principle, 8 * 4 + 1 = 33 points guarantees > 4 in one sub-cube.
            if len(cell) >= 8 * MAX_PORES + 1:
                return False
        qualifying_count += 1

    if qualifying_count <= MAX_PORES:
        return True

    for (cx, cy, cz), cell_pts in grid.items():
        neighbor_pts = []
        for dx in (0, 1):
            nx = cx + dx
            for dy in (-1, 0, 1):
                ny = cy + dy
                for dz in (-1, 0, 1):
                    pts_in_cell = grid.get((nx, ny, cz + dz))
                    if pts_in_cell is not None:
                        neighbor_pts.extend(pts_in_cell)

        if len(neighbor_pts) <= MAX_PORES:
            continue

        # Any cube containing > 4 pores can be shifted so its min-x face passes through
        # one of those pores (px, py, pz); check for a 5.0 x 5.0 (y, z) square in that x-slab.
        for px, py, pz in cell_pts:
            cands = [
                (qy, qz)
                for qx, qy, qz in neighbor_pts
                if 0.0 <= qx - px <= LIMIT
                and abs(qy - py) <= LIMIT
                and abs(qz - pz) <= LIMIT
            ]
            if len(cands) <= MAX_PORES:
                continue

            cands.sort()
            m = len(cands)
            j = 0
            prev_j = -1
            for i in range(m):
                yi = cands[i][0]
                while j < m and cands[j][0] - yi <= LIMIT:
                    j += 1
                if j == prev_j:
                    continue
                prev_j = j
                if j - i > MAX_PORES:
                    zs = sorted(cands[k][1] for k in range(i, j))
                    for k in range(len(zs) - MAX_PORES):
                        if zs[k + MAX_PORES] - zs[k] <= LIMIT:
                            return False

    return True
