import math


def check(part):
    """Return True if the part is accepted, False if rejected.

    Rejects the part if any axis-aligned 5.0 mm cube (closed faces) contains
    the centroids of more than 4 pores with d_eq_mm >= 0.10.
    """
    edge = 5.0
    eps = 1e-12
    limit = edge + eps
    min_d_eq = 0.10
    cell_size = 5.01  # Strictly greater than `limit` and less than 2 * `edge`

    points = [
        (p["centroid"][0], p["centroid"][1], p["centroid"][2])
        for p in part["pores"]
        if p["d_eq_mm"] >= min_d_eq
    ]
    if len(points) <= 4:
        return True

    floor = math.floor
    grid = {}
    for pt in points:
        key = (
            floor(pt[0] / cell_size),
            floor(pt[1] / cell_size),
            floor(pt[2] / cell_size),
        )
        bucket = grid.get(key)
        if bucket is None:
            grid[key] = [pt]
        else:
            bucket.append(pt)
            # A 5.01 mm cube is covered by 8 cubes of edge 5.0 mm;
            # >= 33 points guarantees >= 5 in at least one 5.0 mm cube.
            if len(bucket) >= 33:
                return False

    def has_five_in_square(yz_pts):
        yz_pts.sort()
        n = len(yz_pts)
        j = 0
        for i in range(n - 4):
            y_start = yz_pts[i][0]
            prev_j = j
            while j < n and yz_pts[j][0] - y_start <= limit:
                j += 1
            if j > prev_j and j - i >= 5:
                zs = sorted(yz_pts[k][1] for k in range(i, j))
                for k in range(len(zs) - 4):
                    if zs[k + 4] - zs[k] <= limit:
                        return True
        return False

    grid_get = grid.get
    for (cx, cy, cz), cell_pts in grid.items():
        # Any qualifying cube whose minimum-x point lies in (cx, cy, cz)
        # can only contain points in {cx, cx+1} x {cy-1, cy, cy+1} x {cz-1, cz, cz+1}.
        pool = []
        for dx in (0, 1):
            nx = cx + dx
            for dy in (-1, 0, 1):
                ny = cy + dy
                for dz in (-1, 0, 1):
                    bucket = grid_get((nx, ny, cz + dz))
                    if bucket is not None:
                        pool.extend(bucket)

        if len(pool) <= 4:
            continue

        for x0, y0, z0 in cell_pts:
            nbrs = [
                (y, z)
                for x, y, z in pool
                if x >= x0
                and x - x0 <= limit
                and abs(y - y0) <= limit
                and abs(z - z0) <= limit
            ]
            if len(nbrs) <= 4:
                continue
            # The [x0, x0+limit] x [y0-limit, y0+limit] x [z0-limit, z0+limit]
            # box is covered by 4 cubes of edge `limit` all containing (x0, y0, z0);
            # >= 14 points (p0 plus >= 13 others) guarantees >= 5 in one cube.
            if len(nbrs) >= 14 or has_five_in_square(nbrs):
                return False

    return True
