from collections import defaultdict
import math


def check(part):
    min_d_eq = 0.15
    box_size = 5.0
    max_pores = 3

    pts = [
        (p["centroid"][0], p["centroid"][1], p["centroid"][2])
        for p in part["pores"]
        if p["d_eq_mm"] >= min_d_eq
    ]
    if len(pts) <= max_pores:
        return True

    def has_dense_box(points):
        points.sort(key=lambda p: p[0])
        n = len(points)
        right = 0
        prev_right = 0
        for i in range(n - max_pores):
            x_limit = points[i][0] + box_size
            while right < n and points[right][0] <= x_limit:
                right += 1
            if right - i <= max_pores or right == prev_right:
                continue
            prev_right = right

            x_slice = sorted(points[i:right], key=lambda p: p[1])
            m = len(x_slice)
            y_right = 0
            prev_y_right = 0
            for yi in range(m - max_pores):
                y_limit = x_slice[yi][1] + box_size
                while y_right < m and x_slice[y_right][1] <= y_limit:
                    y_right += 1
                if y_right - yi <= max_pores or y_right == prev_y_right:
                    continue
                prev_y_right = y_right

                zs = sorted(p[2] for p in x_slice[yi:y_right])
                for zi in range(len(zs) - max_pores):
                    if zs[zi + max_pores] <= zs[zi] + box_size:
                        return True
        return False

    # Spatial hash with cell_size > box_size so every 5x5x5 mm cube fits
    # completely inside some 2x2x2 block of grid cells.
    cell_size = 5.5
    grid = defaultdict(list)
    for p in pts:
        cell = (
            math.floor(p[0] / cell_size),
            math.floor(p[1] / cell_size),
            math.floor(p[2] / cell_size),
        )
        bucket = grid[cell]
        bucket.append(p)
        # A 5.5^3 cell partitions into 8 sub-cubes of size 2.75^3 (< 5.0^3);
        # by the pigeonhole principle, > 8 * max_pores points guarantees a violation.
        if len(bucket) > 8 * max_pores:
            return False

    candidate_blocks = set()
    for cx, cy, cz in grid:
        for dx in (0, 1):
            for dy in (0, 1):
                for dz in (0, 1):
                    candidate_blocks.add((cx - dx, cy - dy, cz - dz))

    for bx, by, bz in candidate_blocks:
        block_pts = []
        for dx in (0, 1):
            for dy in (0, 1):
                for dz in (0, 1):
                    cell_pts = grid.get((bx + dx, by + dy, bz + dz))
                    if cell_pts:
                        block_pts.extend(cell_pts)
        if len(block_pts) > max_pores and has_dense_box(block_pts):
            return False

    return True
```

ASSUMPTIONS:
- The 0.15 mm equivalent diameter threshold is inclusive (`d_eq_mm >= 0.15`), and pores below 0.15 mm are ignored.
- The 5 mm x 5 mm x 5 mm reference volume is evaluated as an arbitrarily positioned (sliding) axis-aligned cube anywhere in 3D space, rather than a fixed grid, an arbitrarily rotated cube, or a whole-part average density.
- A pore is considered inside a reference volume if its `centroid` lies within the closed 5 mm x 5 mm x 5 mm cube (inclusive boundaries), rather than using bounding-box intersection or full bounding-box containment.
- Reference volumes do not need to be fully contained inside the part's outer surface (e.g., thin walls are checked with the same 5 mm x 5 mm x 5 mm cube).
- The criterion applies globally to all pores in `part["pores"]` regardless of inspection zones, surface distance, wall thickness, or pore shape/sphericity.

