import math
from decimal import Decimal, ROUND_HALF_UP, InvalidOperation

LIMIT_MM = Decimal("0.5")
REPORT_STEP = Decimal("0.1")


def _reported_size(d_eq):
    """Round an equivalent diameter to the 0.1 mm reporting resolution (half-up)."""
    # repr() gives the shortest decimal string that round-trips the float.
    # This avoids binary artifacts, e.g. 0.55 being stored as 0.55000000000000004.
    return Decimal(repr(float(d_eq))).quantize(REPORT_STEP, rounding=ROUND_HALF_UP)


def _d_eq_of(pore):
    """Return the pore's equivalent diameter in mm, or None if it cannot be determined."""
    d = pore.get("d_eq_mm")
    if d is None:
        v = pore.get("volume_mm3")
        if v is None:
            return None
        try:
            v = float(v)
        except (TypeError, ValueError):
            return None
        if math.isnan(v) or math.isinf(v) or v < 0:
            return None
        # Diameter of the sphere with the same volume
        return (6.0 * v / math.pi) ** (1.0 / 3.0)
    try:
        d = float(d)
    except (TypeError, ValueError):
        return None
    if math.isnan(d) or math.isinf(d) or d < 0:
        return None
    return d


def check(part):
    pores = part.get("pores") or []
    for pore in pores:
        d = _d_eq_of(pore)
        if d is None:
            # Pore size cannot be determined -> cannot demonstrate acceptance
            return False
        try:
            size = _reported_size(d)
        except (InvalidOperation, ValueError, OverflowError):
            return False
        if size > LIMIT_MM:
            return False
    return True
