    DEFAULT_LIMIT = 1.00
    RANK = ["sealing", "machined"]  # highest rank first

    # Group zone boxes by recognized zone type (several boxes may share a type).
    zones_by_type = {"sealing": [], "machined": []}
    for zone in part.get("zones", []) or []:
        name = str(zone.get("name", "")).strip().lower()
        if name in zones_by_type:
            zones_by_type[name].append(zone["box"])

    def contains(box, point):
        xmin, xmax, ymin, ymax, zmin, zmax = box
        x, y, z = point
