    for pore in part.get("pores", []) or []:
        centroid = pore["centroid"]
        limit = DEFAULT_LIMIT
        for zone_type in RANK:
            if any(contains(box, centroid) for box in zones_by_type[zone_type]):
                limit = LIMITS[zone_type]
                break
        if pore["d_eq_mm"] > limit:
            return False

    return True
