def check(part):
    """
    Acceptance criterion:
      No pore with an equivalent diameter above 0.20 mm is permitted in the
      sealing zone. A part without a zone of that name has no pores in it.

    Returns True if accepted, False if rejected.
    """
    D_EQ_LIMIT_MM = 0.20
    SEALING_NAMES = {"sealing", "sealing zone", "sealing_zone", "sealing-zone", "sealingzone"}

    def normalize(name):
        return " ".join(str(name).strip().lower().split())

    def is_sealing(zone):
        n = normalize(zone.get("name", ""))
        return n in SEALING_NAMES or n.replace(" ", "_") in SEALING_NAMES

    def boxes_overlap(a, b):
        # a, b: [xmin, xmax, ymin, ymax, zmin, zmax]; touching boundaries count as overlap
        for i in range(0, 6, 2):
            a_lo, a_hi = min(a[i], a[i + 1]), max(a[i], a[i + 1])
            b_lo, b_hi = min(b[i], b[i + 1]), max(b[i], b[i + 1])
            if a_hi < b_lo or b_hi < a_lo:
                return False
        return True

    def point_in_box(p, box):
        for k in range(3):
            lo, hi = min(box[2 * k], box[2 * k + 1]), max(box[2 * k], box[2 * k + 1])
            if not (lo <= p[k] <= hi):
                return False
        return True

    sealing_boxes = [z["box"] for z in part.get("zones", []) or [] if is_sealing(z)]

    # No sealing zone -> no pores are in it -> criterion trivially satisfied.
    if not sealing_boxes:
        return True

    for pore in part.get("pores", []) or []:
        if pore["d_eq_mm"] <= D_EQ_LIMIT_MM:
            continue
        bbox = pore.get("bbox")
        for box in sealing_boxes:
            if bbox is not None:
                in_zone = boxes_overlap(bbox, box)
            else:
                in_zone = point_in_box(pore["centroid"], box)
            if in_zone:
                return False

    return True
```

ASSUMPTIONS:
- The "sealing zone" is any zone whose name, after trimming whitespace, ignoring case and collapsing internal whitespace, is "sealing", "sealing zone", "sealing_zone", "sealing-zone" or "sealingzone". Other names, such as "seal" or "sealing_face", are not treated as the sealing zone.
- If several zones match that name, the sealing zone is the union of their boxes.
- A pore counts as "in" the sealing zone if its bounding box overlaps any sealing-zone box, even partially. This is conservative: for elongated or diagonal pores, the bounding box can overlap the zone while the pore material itself does not.
- If a pore has no bbox, its centroid is used instead. The pore counts as in the zone if the centroid lies inside a sealing-zone box.
- Zone boundaries are inclusive. A pore or bbox that only touches a zone face counts as inside the zone.
- "Above 0.20 mm" means strictly greater than 0.20. A d_eq_mm of exactly 0.20 is accepted. No floating-point tolerance is applied.
- The equivalent diameter is taken directly from d_eq_mm. It is not recomputed from volume_mm3.
- If the zone or pore list is missing or empty, it is treated as having no entries. A part with no sealing zone, or with no pores, is accepted.
- Box coordinates are normalized with min/max, so a box written with min and max swapped is still handled correctly.
- The other fields are not used, because the criterion does not mention them: part_volume_mm3, nominal_wall_mm, feret_max_mm, sphericity, dist_surface_mm and wall_mm.

```python
def check(part):
    """
    Acceptance criterion:
    No pore with an equivalent diameter above 0.20 mm is permitted in the
    sealing zone. A part without a zone of that name has no pores in it.

    Returns True if accepted, False if rejected.
    """
    D_EQ_LIMIT_MM = 0.20

    def _normalize(name):
        # Case-insensitive; treat spaces, underscores and hyphens alike.
        n = str(name).strip().lower()
        for ch in ("_", "-"):
            n = n.replace(ch, " ")
        return " ".join(n.split())

    accepted_names = {"sealing", "sealing zone"}

    sealing_boxes = [
        z["box"]
        for z in part.get("zones", [])
        if _normalize(z.get("name", "")) in accepted_names
    ]

    # No sealing zone means no pores in it, so the part is accepted.
    if not sealing_boxes:
        return True

    def _boxes_overlap(a, b):
        # Closed intervals: touching boundaries count as overlap.
        for i in range(0, 6, 2):
            a_min, a_max = min(a[i], a[i + 1]), max(a[i], a[i + 1])
            b_min, b_max = min(b[i], b[i + 1]), max(b[i], b[i + 1])
            if a_max < b_min or b_max < a_min:
                return False
        return True

    for pore in part.get("pores", []):
        if pore["d_eq_mm"] <= D_EQ_LIMIT_MM:
            continue
        for box in sealing_boxes:
            if _boxes_overlap(pore["bbox"], box):
                return False

    return True
```

