def check(part):
    import math

    pores = [pore for pore in part["pores"] if pore["d_eq_mm"] >= 0.05]
    count = len(pores)

    parent = list(range(count))
    rank = [0] * count

    def find(index):
        while parent[index] != index:
            parent[index] = parent[parent[index]]
            index = parent[index]
        return index

    def union(left, right):
        left_root = find(left)
        right_root = find(right)

        if left_root == right_root:
            return

        if rank[left_root] < rank[right_root]:
            parent[left_root] = right_root
        elif rank[left_root] > rank[right_root]:
            parent[right_root] = left_root
        else:
            parent[right_root] = left_root
            rank[left_root] += 1

    for i in range(count):
        for j in range(i + 1, count):
            centroid_distance = math.dist(
                pores[i]["centroid"], pores[j]["centroid"]
            )
            gap = centroid_distance - (
                pores[i]["d_eq_mm"] + pores[j]["d_eq_mm"]
            ) / 2.0

            if gap < 0.50:
                union(i, j)

    clusters = {}
    for index, pore in enumerate(pores):
        root = find(index)
        clusters.setdefault(root, []).append(pore["d_eq_mm"])

    for diameters in clusters.values():
        if len(diameters) > 5:
            return False
        if math.fsum(diameters) > 1.0:
            return False

    return True
