import math
from collections import defaultdict


def check(part):
    considered = []
    max_d_eq = 0.0
    for pore in part.get("pores", []):
        d_eq = pore["d_eq_mm"]
        if d_eq >= 0.05:
            if d_eq > 1.0:
                return False
            considered.append((pore["centroid"], d_eq))
            if d_eq > max_d_eq:
                max_d_eq = d_eq

    n = len(considered)
    if n == 0:
        return True

    parent = list(range(n))
    size = [1] * n

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(i, j):
        ri = find(i)
        rj = find(j)
        if ri == rj:
            return True
        if size[ri] < size[rj]:
            ri, rj = rj, ri
        parent[rj] = ri
        size[ri] += size[rj]
        return size[ri] <= 5

    # Any two neighbours have centroid distance < 0.50 + max_d_eq
    cell_size = 0.50 + max_d_eq + 1e-6
    grid = defaultdict(list)
    for idx, (centroid, _) in enumerate(considered):
        key = (
            math.floor(centroid[0] / cell_size),
            math.floor(centroid[1] / cell_size),
            math.floor(centroid[2] / cell_size),
        )
        grid[key].append(idx)

    forward_offsets = [
        (dx, dy, dz)
        for dx in (-1, 0, 1)
        for dy in (-1, 0, 1)
        for dz in (-1, 0, 1)
        if (dx, dy, dz) > (0, 0, 0)
    ]

    for cell, indices in grid.items():
        m = len(indices)
        for a in range(m):
            i = indices[a]
            ci, di = considered[i]
            for b in range(a + 1, m):
                j = indices[b]
                if find(i) == find(j):
                    continue
                cj, dj = considered[j]
                if math.dist(ci, cj) - 0.5 * (di + dj) < 0.50:
                    if not union(i, j):
                        return False

        gx, gy, gz = cell
        for dx, dy, dz in forward_offsets:
            nbr_indices = grid.get((gx + dx, gy + dy, gz + dz))
            if not nbr_indices:
                continue
            for i in indices:
                ci, di = considered[i]
                for j in nbr_indices:
                    if find(i) == find(j):
                        continue
                    cj, dj = considered[j]
                    if math.dist(ci, cj) - 0.5 * (di + dj) < 0.50:
                        if not union(i, j):
                            return False

    clusters = defaultdict(list)
    for idx, (_, d_eq) in enumerate(considered):
        clusters[find(idx)].append(d_eq)

    for d_eqs in clusters.values():
        if math.fsum(d_eqs) > 1.0:
            return False

    return True
```

ASSUMPTIONS:
- Pores with `d_eq_mm < 0.05` are ignored completely and cannot act as intermediate bridges between considered pores or contribute to cluster counts or summed diameters.
- Boundary inequalities are interpreted literally: `d_eq_mm >= 0.05` is considered, `gap < 0.50` defines neighbours (exactly 0.50 mm is not a neighbour), and rejection occurs for cluster count `> 5` (5 is accepted) or summed equivalent diameter `> 1.0` (1.0 mm is accepted).
