    if not pores:
        return True

    # Any single considered pore with d_eq_mm > 1.0 mm forms (or belongs to)
    # a cluster whose summed equivalent diameter exceeds 1.0 mm.
    for p in pores:
        if p["d_eq_mm"] > 1.0:
            return False

    n = len(pores)
    parent = list(range(n))
    rank = [0] * n

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(i, j):
        ri, rj = find(i), find(j)
        if ri == rj:
            return
        if rank[ri] < rank[rj]:
            ri, rj = rj, ri
        parent[rj] = ri
        if rank[ri] == rank[rj]:
            rank[ri] += 1

    # All remaining pores have d_eq_mm <= 1.0 mm, so any two neighbours have
    # centroid distance < 0.50 + 0.5 * (1.0 + 1.0) = 1.50 mm.
    cell_size = 1.6
    grid = defaultdict(list)

    for idx, p in enumerate(pores):
        x, y, z = p["centroid"]
        cx = math.floor(x / cell_size)
        cy = math.floor(y / cell_size)
        cz = math.floor(z / cell_size)
        d1 = p["d_eq_mm"]

        for dx in (-1, 0, 1):
            for dy in (-1, 0, 1):
                for dz in (-1, 0, 1):
                    cell_pores = grid.get((cx + dx, cy + dy, cz + dz))
                    if not cell_pores:
                        continue
                    for other_idx in cell_pores:
                        if find(idx) == find(other_idx):
                            continue
                        other = pores[other_idx]
                        dist = math.dist(p["centroid"], other["centroid"])
                        gap = dist - 0.5 * (d1 + other["d_eq_mm"])
