    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    # Any two neighbours must have centroid distance < 0.50 + 0.5 * (d1 + d2) <= 0.50 + max_d.
    cell_size = 0.50 + max_d + 1e-6
    grid = defaultdict(list)
    neighbor_offsets = [
        (dx, dy, dz)
        for dx in (-1, 0, 1)
        for dy in (-1, 0, 1)
        for dz in (-1, 0, 1)
    ]

    for i, (ci, di) in enumerate(pores):
        cx = math.floor(ci[0] / cell_size)
        cy = math.floor(ci[1] / cell_size)
        cz = math.floor(ci[2] / cell_size)

        ri = i
        for dx, dy, dz in neighbor_offsets:
            cell = grid.get((cx + dx, cy + dy, cz + dz))
            if not cell:
                continue
            for j in cell:
                rj = find(j)
                if ri == rj:
                    continue
                cj, dj = pores[j]
                if math.dist(ci, cj) - 0.5 * (di + dj) < 0.50:
                    if len(cluster_diams[ri]) + len(cluster_diams[rj]) > 5:
                        return False
                    if len(cluster_diams[ri]) < len(cluster_diams[rj]):
                        ri, rj = rj, ri
                    parent[rj] = ri
                    cluster_diams[ri].extend(cluster_diams[rj])
                    cluster_diams[rj] = []
                    if math.fsum(cluster_diams[ri]) > 1.0:
                        return False

        grid[(cx, cy, cz)].append(i)

    return True
