def check(part: dict) -> bool:
    """Check that no pore with d_eq_mm > 0.20 mm is in the sealing zone."""
    def is_sealing_zone(name: str) -> bool:
        normalized = " ".join(
            name.strip().lower().replace("_", " ").replace("-", " ").split()
        )
        return normalized in {"sealing", "sealing zone"}

    def boxes_intersect(box_a: list, box_b: list) -> bool:
        ax0, ax1, ay0, ay1, az0, az1 = box_a
        bx0, bx1, by0, by1, bz0, bz1 = box_b
        return (
            ax0 <= bx1 and ax1 >= bx0
            and ay0 <= by1 and ay1 >= by0
            and az0 <= bz1 and az1 >= bz0
        )

    sealing_boxes = [
        zone["box"]
        for zone in part.get("zones", [])
        if is_sealing_zone(zone["name"])
    ]
    if not sealing_boxes:
        return True

    for pore in part.get("pores", []):
        if pore["d_eq_mm"] > 0.20:
            pore_bbox = pore["bbox"]
            if any(boxes_intersect(pore_bbox, z_box) for z_box in sealing_boxes):
