```python
import math

# ---------------------------------------------------------------------------
# Criterion: "Pores with an equivalent diameter of 0.20 mm or more must be
# separated, centroid to centroid, by at least twice the pore diameter."
# ---------------------------------------------------------------------------

MIN_D_EQ_MM = 0.20        # pores with d_eq >= this value are subject to the rule
SPACING_FACTOR = 2.0      # required spacing = SPACING_FACTOR * reference diameter
TOL = 1e-9                # floating-point tolerance for inclusive comparisons

# Interpretation switches (see assumptions):
#   PAIR_MODE:     "both"   -> check pairs where both pores are >= 0.20 mm
#                  "either" -> check pairs where at least one pore is >= 0.20 mm
#   DIAMETER_RULE: "larger" | "smaller" | "mean"  (diameter used for unequal pairs)
PAIR_MODE = "both"
DIAMETER_RULE = "larger"


def _qualifies(pore):
    return pore["d_eq_mm"] >= MIN_D_EQ_MM - TOL


def _reference_diameter(d1, d2):
    if DIAMETER_RULE == "larger":
        return max(d1, d2)
    if DIAMETER_RULE == "smaller":
        return min(d1, d2)
    if DIAMETER_RULE == "mean":
        return 0.5 * (d1 + d2)
    raise ValueError("Unknown DIAMETER_RULE: %r" % DIAMETER_RULE)


def _distance(c1, c2):
    return math.sqrt(sum((a - b) ** 2 for a, b in zip(c1, c2)))


def find_violations(part):
    """Return a list of (id_a, id_b, distance_mm, required_mm) for failing pairs."""
    pores = part.get("pores", [])
    violations = []
    n = len(pores)
    for i in range(n):
        pi = pores[i]
        qi = _qualifies(pi)
        for j in range(i + 1, n):
            pj = pores[j]
            qj = _qualifies(pj)

            if PAIR_MODE == "both":
                if not (qi and qj):
                    continue
            elif PAIR_MODE == "either":
                if not (qi or qj):
                    continue
            else:
                raise ValueError("Unknown PAIR_MODE: %r" % PAIR_MODE)

            required = SPACING_FACTOR * _reference_diameter(pi["d_eq_mm"], pj["d_eq_mm"])
            dist = _distance(pi["centroid"], pj["centroid"])
            if dist < required - TOL:
                violations.append((pi["id"], pj["id"], dist, required))
    return violations


def check(part):
    """Return True to accept the part, False to reject it."""
    return len(find_violations(part)) == 0
```

The helper `find_violations(part)` returns the offending pore pairs, with their measured and required spacing, so a rejection can be traced back to specific pores. `check(part)` itself returns only True/False, as requested.

