SIZE_THRESHOLD_MM = 0.20          # pores with d_eq >= this are subject to the rule
SPACING_FACTOR = 2.0              # "at least twice the pore diameter"
PAIR_DIAMETER = "max"             # "max" (strictest), "min", or "mean"
INCLUDE_SMALL_NEIGHBOURS = False  # True: qualifying pores must also be spaced from smaller pores
ABS_TOL_MM = 1e-9                 # tolerance so exact-boundary distances count as "at least"


def _pair_diameter(d1, d2):
    if PAIR_DIAMETER == "max":
        return max(d1, d2)
    if PAIR_DIAMETER == "min":
        return min(d1, d2)
    if PAIR_DIAMETER == "mean":
        return 0.5 * (d1 + d2)
    raise ValueError("PAIR_DIAMETER must be 'max', 'min', or 'mean'")


def _governing_diameter(d1, d2, q1, q2):
    """Diameter that sets the required spacing for a pair (q = pore is qualifying)."""
    if q1 and q2:
        return _pair_diameter(d1, d2)
    # Only one pore qualifies (possible only when INCLUDE_SMALL_NEIGHBOURS is True):
    # the requirement comes from the qualifying pore's own diameter.
    return d1 if q1 else d2


def check(part):
    """Return True (accept) if all pores with d_eq >= 0.20 mm are spaced, centroid to
    centroid, at least twice the pore diameter apart; otherwise False (reject)."""
    pores = part.get("pores", []) or []

    entries = []
    for p in pores:
        d = float(p["d_eq_mm"])
        c = tuple(float(v) for v in p["centroid"])
        qualifies = d >= SIZE_THRESHOLD_MM
        entries.append((c, d, qualifies))

    n = len(entries)
    for i in range(n):
        ci, di, qi = entries[i]
        for j in range(i + 1, n):
            cj, dj, qj = entries[j]

            if qi and qj:
                pass  # both pores are subject to the rule
            elif INCLUDE_SMALL_NEIGHBOURS and (qi or qj):
                pass  # one qualifying pore next to a smaller pore
            else:
                continue

            required = SPACING_FACTOR * _governing_diameter(di, dj, qi, qj)
            distance = math.dist(ci, cj)
            if distance + ABS_TOL_MM < required:
                return False

    return True
```

Notes:
- With the defaults, two 0.30 mm pores need ≥ 0.60 mm between centroids. A 0.30 mm pore and a 0.50 mm pore need ≥ 1.00 mm.
- The pairwise loop is O(n²). This is fine for typical pore counts (up to a few thousand). For very large datasets, add a grid-based spatial index.
- If your specification owner settles the ambiguities differently, change only the constants at the top.

The requirement leaves some choices open, so I've made each one explicit and configurable in the code below.

## Interpretation choices

| Ambiguity | Default chosen | Alternative |
|---|---|---|
| Which pores are checked | Only pairs where **both** pores have `d_eq_mm` ≥ 0.20. The sentence scopes the rule to "pores with an equivalent diameter of 0.20 mm or more." | Check every pore ≥ 0.20 against **all** other pores, including smaller ones (`PAIR_SCOPE = "any"`). |
| "the pore diameter" in a pair of different sizes | The **larger** `d_eq_mm` of the two. This is the stricter reading. | The smaller (lenient), the mean, or `d1 + d2` (twice the mean, used in some specs). |
| Which diameter | `d_eq_mm`. It matches the measure used in the size threshold. | `feret_max_mm`. This is stricter for elongated or shrinkage pores. |
| Boundaries | "0.20 mm or more" means `>=`. "At least" means a distance exactly equal to the limit passes. | – |
| Zones | Not used. The requirement applies to the whole part. | – |
| Float tolerance | A tiny epsilon (1e-9 mm) so values that sit exactly on a limit aren't flipped by rounding. | Set it to 0 for strict comparisons. |

Please confirm these with whoever owns the specification. The choice of reference diameter has the biggest effect on results.

```python
import math

# ---- Configurable interpretation parameters ----
SIZE_THRESHOLD_MM = 0.20      # "0.20 mm or more" -> inclusive
SPACING_FACTOR = 2.0          # "at least twice the pore diameter"
DIAMETER_KEY = "d_eq_mm"      # diameter used for both threshold and spacing
PAIR_SCOPE = "both"           # "both": both pores >= threshold; "any": at least one pore >= threshold
PAIR_REFERENCE = "max"        # "max" (conservative), "min", "mean", or "sum" (d1 + d2)
EPS = 1e-9                    # mm; guards against floating-point noise at exact limits


def _reference_diameter(d1, d2):
    if PAIR_REFERENCE == "max":
        return max(d1, d2)
    if PAIR_REFERENCE == "min":
        return min(d1, d2)
    if PAIR_REFERENCE == "mean":
        return 0.5 * (d1 + d2)
    if PAIR_REFERENCE == "sum":
        # SPACING_FACTOR * (d1 + d2) / 2 -> with factor 2 this yields d1 + d2
        return 0.5 * (d1 + d2)
    raise ValueError(f"Unknown PAIR_REFERENCE: {PAIR_REFERENCE}")


def find_violations(part):
    """Return a list of (id_a, id_b, distance_mm, required_mm) for pairs that are too close."""
    pores = part.get("pores", []) or []
    large = [p for p in pores if p[DIAMETER_KEY] >= SIZE_THRESHOLD_MM - EPS]

    if PAIR_SCOPE == "both":
        candidates_b = large
    elif PAIR_SCOPE == "any":
        candidates_b = pores
    else:
        raise ValueError(f"Unknown PAIR_SCOPE: {PAIR_SCOPE}")

    violations = []
    seen = set()
    for a in large:
        for b in candidates_b:
            if a is b:
                continue
            key = frozenset((id(a), id(b)))
            if key in seen:
                continue
            seen.add(key)

            dist = math.dist(a["centroid"], b["centroid"])
            ref_d = _reference_diameter(a[DIAMETER_KEY], b[DIAMETER_KEY])
            required = SPACING_FACTOR * ref_d
            if dist < required - EPS:
                violations.append((a["id"], b["id"], dist, required))
    return violations


def check(part) -> bool:
    """True if every qualifying pore pair satisfies the minimum centroid spacing."""
    return not find_violations(part)
```

## Notes

- **Helper function:** `find_violations` is provided alongside `check`. It lists the offending pore pairs, the measured distance and the required distance, which you can use in an inspection report.
- **Edge cases:** a part with zero or one qualifying pore passes.
- **Runtime:** the pairwise check is O(n²). That is fine for typical CT pore counts (thousands of pores). For very large pore lists, add a spatial grid with cell size equal to `SPACING_FACTOR` × the largest diameter.

