        volume_mm3 = float(part["part_volume_mm3"])
        pores = part["pores"]
    except (KeyError, TypeError, ValueError):
        return False

    if not math.isfinite(volume_mm3) or volume_mm3 <= 0:
        return False
    if not isinstance(pores, list):
        return False

    # 1 cm³ = 1000 mm³. Every pore record is counted once.
    return len(pores) * 1000 <= 10 * volume_mm3
