def check(part):
    sealing_boxes = [
        tuple(zone["box"])
        for zone in part["zones"]
        if zone["name"] == "sealing"
    ]

    # An absent sealing zone is defined as containing no pores.
    if not sealing_boxes:
        return True

    def union_area_yz(rectangles):
        """Area of the union of axis-aligned [ymin, ymax, zmin, zmax] rectangles."""
        y_edges = sorted({
            edge
            for ymin, ymax, _, _ in rectangles
            for edge in (ymin, ymax)
        })
        area = 0.0

        for y0, y1 in zip(y_edges, y_edges[1:]):
            if y1 <= y0:
                continue

            z_intervals = sorted(
                (zmin, zmax)
                for ymin, ymax, zmin, zmax in rectangles
                if ymin < y1 and ymax > y0 and zmax > zmin
            )
            if not z_intervals:
                continue

            covered_z = 0.0
            start, end = z_intervals[0]
            for next_start, next_end in z_intervals[1:]:
                if next_start <= end:
                    end = max(end, next_end)
                else:
                    covered_z += end - start
                    start, end = next_start, next_end
            covered_z += end - start

            area += (y1 - y0) * covered_z

        return area

    def union_volume(boxes):
        """Volume of the union of axis-aligned boxes."""
        x_edges = sorted({
            edge
            for xmin, xmax, _, _, _, _ in boxes
            for edge in (xmin, xmax)
        })
        volume = 0.0

        for x0, x1 in zip(x_edges, x_edges[1:]):
            if x1 <= x0:
                continue

            yz_rectangles = [
                (ymin, ymax, zmin, zmax)
                for xmin, xmax, ymin, ymax, zmin, zmax in boxes
                if xmin < x1 and xmax > x0
            ]
            volume += (x1 - x0) * union_area_yz(yz_rectangles)

        return volume

    sealing_volume = union_volume(sealing_boxes)
    if sealing_volume <= 0.0:
        return False

    pore_volume = 0.0
    for pore in part["pores"]:
        x, y, z = pore["centroid"]
        if any(
            xmin <= x <= xmax
            and ymin <= y <= ymax
            and zmin <= z <= zmax
            for xmin, xmax, ymin, ymax, zmin, zmax in sealing_boxes
        ):
            pore_volume += pore["volume_mm3"]

    return pore_volume <= 0.002 * sealing_volume
```

ASSUMPTIONS:
- Zone names are matched exactly and case-sensitively to `"sealing"`.
- All zones named `"sealing"` collectively form one sealing region.
- Overlapping sealing boxes are unioned, so their shared volume is not counted twice.
- A pore belongs to the sealing region when its centroid lies inside or on the boundary of any sealing box.
- The full volume of a qualifying pore is counted, even if part of that pore extends outside the sealing region.
- Each pore is counted only once even when its centroid lies in multiple overlapping sealing boxes.
- Sealing-zone porosity is total qualifying pore volume divided by the geometric union volume of the sealing boxes.
- Sealing boxes are assumed to represent inspected part volume and not empty space outside the part.
- A missing sealing zone has zero sealing-zone porosity and is accepted, as stated.
- Exactly 0.2% porosity is accepted because the criterion says it must not exceed 0.2%.
- A named sealing region with zero or negative geometric volume is rejected because its porosity is undefined.

