def check(part):
    """
    A pore is assigned to the sealing zone when its centroid is inside any
    zone named "sealing". Overlapping sealing boxes are treated as one union.
    Porosity is total assigned pore volume divided by that union's volume.
    """
    sealing_boxes = [
        zone["box"] for zone in part["zones"] if zone["name"] == "sealing"
    ]

    if not sealing_boxes:
        return len(part["pores"]) == 0

    # Calculate the exact union volume of the axis-aligned sealing boxes.
    x_coords = sorted({x for box in sealing_boxes for x in box[:2]})
    sealing_volume = 0.0

    for x0, x1 in zip(x_coords, x_coords[1:]):
        if x1 <= x0:
            continue

        active_boxes = [
            box for box in sealing_boxes
            if box[0] < x1 and box[1] > x0
        ]
        y_coords = sorted({y for box in active_boxes for y in box[2:4]})

        yz_area = 0.0
        for y0, y1 in zip(y_coords, y_coords[1:]):
            if y1 <= y0:
                continue

            z_intervals = sorted(
                (box[4], box[5])
                for box in active_boxes
                if box[2] < y1 and box[3] > y0 and box[5] > box[4]
            )

            covered_z = 0.0
            if z_intervals:
                start, end = z_intervals[0]
                for next_start, next_end in z_intervals[1:]:
                    if next_start <= end:
                        end = max(end, next_end)
                    else:
                        covered_z += end - start
                        start, end = next_start, next_end
                covered_z += end - start

            yz_area += (y1 - y0) * covered_z

        sealing_volume += (x1 - x0) * yz_area

    if sealing_volume <= 0.0:
        return False

    def centroid_in_sealing_zone(pore):
        x, y, z = pore["centroid"]
        return any(
            box[0] <= x <= box[1]
            and box[2] <= y <= box[3]
            and box[4] <= z <= box[5]
            for box in sealing_boxes
        )

    pore_volume = sum(
        pore["volume_mm3"]
        for pore in part["pores"]
        if centroid_in_sealing_zone(pore)
    )

    return pore_volume / sealing_volume <= 0.002
