from itertools import combinations
from math import sqrt


def check(part):
    """
    Treat pore spacing as the shortest Euclidean distance between their
    axis-aligned bounding boxes (a conservative boundary-to-boundary measure).
    """
    relevant_pores = [
        pore for pore in part["pores"]
        if pore["d_eq_mm"] >= 0.20
    ]

    def bbox_distance(a, b):
        squared_distance = 0.0
        for axis in range(3):
            a_min, a_max = a[2 * axis], a[2 * axis + 1]
            b_min, b_max = b[2 * axis], b[2 * axis + 1]

            if a_max < b_min:
                gap = b_min - a_max
            elif b_max < a_min:
                gap = a_min - b_max
            else:
                gap = 0.0

            squared_distance += gap * gap

        return sqrt(squared_distance)

    return all(
        bbox_distance(pore_a["bbox"], pore_b["bbox"]) >= 1.0
        for pore_a, pore_b in combinations(relevant_pores, 2)
    )
