def check(part) -> bool:
    """
    Accept if no axis-aligned 5 mm cube contains more than three pores
    whose equivalent diameter is at least 0.15 mm.

    A pore is assigned to a reference volume by its centroid. Cube
    boundaries are inclusive.
    """
    cube_size = 5.0
    max_pores = 3

    points = sorted(
        tuple(pore["centroid"])
        for pore in part["pores"]
        if pore["d_eq_mm"] >= 0.15
    )

    if len(points) <= max_pores:
        return True

    # It is sufficient to test cubes whose lower x, y, and z faces pass
    # through pore centroids.
    for x_start_index, (x_min, _, _) in enumerate(points):
        x_band = []
        for point in points[x_start_index:]:
            if point[0] > x_min + cube_size:
                break
            x_band.append(point)

        if len(x_band) <= max_pores:
            continue

        x_band.sort(key=lambda point: point[1])

        for y_start_index, (_, y_min, _) in enumerate(x_band):
            if len(x_band) - y_start_index <= max_pores:
                break

            z_values = []
            for point in x_band[y_start_index:]:
                if point[1] > y_min + cube_size:
                    break
                z_values.append(point[2])

            if len(z_values) <= max_pores:
                continue

            z_values.sort()
            z_left = 0

            for z_right, z_max in enumerate(z_values):
                while z_max - z_values[z_left] > cube_size:
                    z_left += 1

                if z_right - z_left + 1 > max_pores:
                    return False

    return True
