import math


def check(part):
    """Return True if porosity does not exceed 1% in any 10 mm x 10 mm reference area."""
    REF_SIDE = 10.0
    MAX_AREA = 1.0  # 1% of (10 mm x 10 mm = 100 mm^2)
    TOL = 1e-9
    SQRT_PI_HALF = 0.5 * math.sqrt(math.pi)

    pores_raw = part.get("pores", [])
    if not pores_raw:
        return True

    def _circle_antideriv(u):
        if u <= -1.0:
            return -0.25 * math.pi
        if u >= 1.0:
            return 0.25 * math.pi
        return 0.5 * (u * math.sqrt(max(0.0, 1.0 - u * u)) + math.asin(u))

    def _ellipse_rect_area(cx, cy, a, b, x1, x2, y1, y2):
        if a <= 0.0 or b <= 0.0 or x1 >= x2 or y1 >= y2:
            return 0.0
        u1 = (x1 - cx) / a
        u2 = (x2 - cx) / a
        v1 = (y1 - cy) / b
        v2 = (y2 - cy) / b
        if u2 <= -1.0 or u1 >= 1.0 or v2 <= -1.0 or v1 >= 1.0:
            return 0.0
        if u1 <= -1.0 and u2 >= 1.0 and v1 <= -1.0 and v2 >= 1.0:
            return math.pi * a * b

        u1 = max(-1.0, u1)
        u2 = min(1.0, u2)
        v1 = max(-1.0, v1)
        v2 = min(1.0, v2)
        if u1 >= u2 or v1 >= v2:
            return 0.0

        pts = [u1, u2]
        for v in (v1, v2):
            v_sq = v * v
            if v_sq < 1.0:
                r = math.sqrt(1.0 - v_sq)
                if u1 < -r < u2:
                    pts.append(-r)
                if u1 < r < u2:
                    pts.append(r)
        pts.sort()

        total = 0.0
        for idx in range(len(pts) - 1):
            p = pts[idx]
            q = pts[idx + 1]
            if q - p <= 1e-15:
                continue
            m = 0.5 * (p + q)
            sm = math.sqrt(max(0.0, 1.0 - m * m))
            if v2 <= -sm or v1 >= sm:
                continue
            if v2 >= sm:
                hi = _circle_antideriv(q) - _circle_antideriv(p)
            else:
                hi = v2 * (q - p)
            if v1 <= -sm:
                lo = -(_circle_antideriv(q) - _circle_antideriv(p))
            else:
                lo = v1 * (q - p)
            total += hi - lo

        return a * b * total

    # Preprocess pores into volume-conserving bounding-box ellipsoids (or spheres if bbox invalid).
    pores = []
    for p in pores_raw:
        vol = float(p.get("volume_mm3", 0.0))
        d_eq = float(p.get("d_eq_mm", 0.0))
        if vol <= 0.0:
            if d_eq > 0.0:
                vol = (math.pi / 6.0) * (d_eq ** 3)
            else:
                continue
        if d_eq <= 0.0:
            d_eq = ((6.0 * vol) / math.pi) ** (1.0 / 3.0)

        bbox = p.get("bbox")
        centroid = p.get("centroid")
        valid_bbox = False
        if bbox is not None and len(bbox) == 6:
            xmin, xmax, ymin, ymax, zmin, zmax = (float(val) for val in bbox)
            lx = xmax - xmin
            ly = ymax - ymin
            lz = zmax - zmin
            if lx > 0.0 and ly > 0.0 and lz > 0.0 and (lx * ly * lz) >= vol * 0.999:
                cx = 0.5 * (xmin + xmax)
                cy = 0.5 * (ymin + ymax)
                cz = 0.5 * (zmin + zmax)
                valid_bbox = True

        if not valid_bbox:
            if centroid is None or len(centroid) != 3:
                continue
            cx, cy, cz = (float(val) for val in centroid)
            lx = ly = lz = d_eq

        pores.append(((cx, cy, cz), (lx, ly, lz), vol))

    if not pores:
        return True

    # Fast single-pore pre-check along all three principal slice orientations.
    axis_triples = ((2, 0, 1), (1, 0, 2), (0, 1, 2))  # (normal_axis, u_axis, v_axis)
    for center, dims, vol in pores:
        for k, i, j in axis_triples:
