                    dens = min(1.0, a_peak / ell_area)
                    clipped = dens * _ellipse_rect_area(
                        0.0, 0.0, a, b, -0.5 * REF_SIDE, 0.5 * REF_SIDE,
                        -0.5 * REF_SIDE, 0.5 * REF_SIDE
                    )
                else:
                    clipped = (a_peak / (lu * lv)) * min(lu, REF_SIDE) * min(lv, REF_SIDE)
