    def _pore_window_area(sp, U, V):
        u1, u2, v1, v2, rect_dens, _, u0, v0, a, b, use_ell, ell_dens, _ = sp
        if use_ell:
            return ell_dens * _ellipse_rect_area(
                u0, v0, a, b, U, U + REF_SIDE, V, V + REF_SIDE
            )
        ou = min(u2, U + REF_SIDE) - max(u1, U)
        if ou <= 0.0:
            return 0.0
        ov = min(v2, V + REF_SIDE) - max(v1, V)
        if ov <= 0.0:
