        return rect_dens * ou * ov

    def _exact_window_area(U, V, u_active, slice_pores):
        area1 = 0.0
        min_ex = float("inf")
        max_ex = float("-inf")
        min_ey = float("inf")
        max_ey = float("-inf")
        involved = []
        for idx in u_active:
            sp = slice_pores[idx]
            u1, u2, v1, v2, _, _, u0, v0, a, b, _, _, _ = sp
            if v2 <= V or v1 >= V + REF_SIDE:
