        axis_peak_cap = []
        w_events = []

        for p_idx, (center, dims, vol) in enumerate(pores):
            w0 = center[k]
            lw = dims[k]
            h = 0.5 * lw
            lu = dims[i]
            lv = dims[j]
            lu_lv = lu * lv
            a_peak_raw = (1.5 * vol) / lw
            a_peak_cap = a_peak_raw if a_peak_raw < lu_lv else lu_lv

            axis_data.append((w0, h, a_peak_raw, lu_lv, center[i], center[j], lu, lv))
            axis_peak_cap.append(a_peak_cap)
            w_events.append((w0 - h, 2, p_idx))  # entry
            w_events.append((w0, 1, p_idx))      # center
            w_events.append((w0 + h, 0, p_idx))  # exit

        def _check_slice(w, active_set, w_interval):
            slice_pores = []
            total_slice_area = 0.0
            for p_idx in active_set:
                w0, h, a_peak_raw, lu_lv, u0, v0, lu, lv = axis_data[p_idx]
                t = (w - w0) / h
                if t <= -1.0 or t >= 1.0:
                    continue
                s2 = 1.0 - t * t
                area = a_peak_raw * s2
                if area > lu_lv:
                    area = lu_lv
                if area <= 0.0:
                    continue

                s = math.sqrt(s2)
                a = 0.5 * lu * s
                b = 0.5 * lv * s
                ell_area = math.pi * a * b
                if area <= ell_area * (1.0 + 1e-9):
                    use_ell = True
                    ell_dens = min(1.0, area / ell_area)
                    ru = a * SQRT_PI_HALF
                    rv = b * SQRT_PI_HALF
                else:
