                slice_pores.append((
                    u0 - ru, u0 + ru, v0 - rv, v0 + rv,
                    rect_dens, area, u0, v0, a, b, use_ell, ell_dens, p_idx
                ))
                total_slice_area += area

            peak_threshold = 0.45 if w_interval is not None else 0.85
            if total_slice_area <= peak_threshold:
