                u_events.append((u1 - REF_SIDE, 2, idx))  # enters [U, U + REF_SIDE]
                u_events.append((u2, 0, idx))             # exits [U, U + REF_SIDE]
                u_events.append((u1, 1, idx))             # candidate U
                u_events.append((u2 - REF_SIDE, 1, idx))  # candidate U
            u_events.sort()

