                        weight = sp[4] * ou
                        v1, v2 = sp[2], sp[3]
                        strip_possible += weight * (v2 - v1)
                        v_events.append((v1 - REF_SIDE, weight))
                        v_events.append((v2 - REF_SIDE, -weight))
                        v_events.append((v1, -weight))
                        v_events.append((v2, weight))

                    if strip_possible <= peak_threshold - 1e-6 or not v_events:
                        continue

                    v_events.sort()
                    val = 0.0
                    slope = 0.0
                    prev_v = v_events[0][0]
                    n_ve = len(v_events)
                    vi = 0
                    while vi < n_ve:
                        v = v_events[vi][0]
                        if v > prev_v:
                            val += slope * (v - prev_v)
                        prev_slope = slope
                        while vi < n_ve and v_events[vi][0] == v:
