                                for s_idx in u_active:
                                    sp = slice_pores[s_idx]
                                    if sp[3] <= v or sp[2] >= v + REF_SIDE:
                                        continue
                                    ou = min(sp[1], U + REF_SIDE) - max(sp[0], U)
                                    ov = min(sp[3], v + REF_SIDE) - max(sp[2], v)
                                    if ou > 0.0 and ov > 0.0:
                                        frac = (ou * ov) / ((sp[1] - sp[0]) * (sp[3] - sp[2]))
                                        w0_p, h_p, a_peak_raw_p, _, _, _, _, _ = axis_data[sp[12]]
                                        c = frac * a_peak_raw_p / (h_p * h_p)
