        w_events.sort()
        active = set()
        active_peak_sum = 0.0
        n_ev = len(w_events)
        ei = 0
        prev_w = w_events[0][0]

        while ei < n_ev:
            curr_w = w_events[ei][0]
            if curr_w > prev_w and active and active_peak_sum > MAX_AREA - 1e-6:
                ub = 0.0
                for p_idx in active:
                    w0, h, a_peak_raw, lu_lv, _, _, _, _ = axis_data[p_idx]
                    w_near = prev_w if w0 <= prev_w else curr_w
                    t = (w_near - w0) / h
                    if -1.0 < t < 1.0:
