            has_center = False
            while ei < n_ev and w_events[ei][0] == curr_w:
                _, etype, p_idx = w_events[ei]
                if etype == 0:
                    active.discard(p_idx)
                    active_peak_sum -= axis_peak_cap[p_idx]
                    if not active:
                        active_peak_sum = 0.0
                elif etype == 1:
                    has_center = True
                else:
                    active.add(p_idx)
                    active_peak_sum += axis_peak_cap[p_idx]
                ei += 1

            if has_center and active and active_peak_sum > MAX_AREA - 1e-6:
                rejected, _ = _check_slice(curr_w, active, None)
                if rejected:
                    return False

            prev_w = curr_w

    return True
