import math


def check(part):
    """Return True if porosity does not exceed 1% in any 10 mm x 10 mm reference area."""
    pores_raw = part.get("pores") or []
    if not pores_raw:
        return True

    WIN = 10.0
    HALF_WIN = 5.0
    # 1% of 10 mm x 10 mm (100 mm^2) = 1.0 mm^2
    LIMIT = 1.0 + 1e-9
    PRUNE_LIMIT = 1.0 - 1e-7

    # Preprocess pores into (xc, yc, zc, a, b, c, vol) axis-aligned ellipsoids
    # using bbox extents and exact volume (falling back to equivalent sphere if needed).
    pores = []
    for p in pores_raw:
        vol = float(p.get("volume_mm3", 0.0))
        if vol <= 0.0:
            continue
        cx, cy, cz = p["centroid"]
        cx, cy, cz = float(cx), float(cy), float(cz)
        r_eq = (3.0 * vol / (4.0 * math.pi)) ** (1.0 / 3.0)

        bbox = p.get("bbox")
        if bbox is not None and len(bbox) == 6:
            xmin, xmax, ymin, ymax, zmin, zmax = (float(v) for v in bbox)
            a = 0.5 * (xmax - xmin)
            b = 0.5 * (ymax - ymin)
            c = 0.5 * (zmax - zmin)
            xc = 0.5 * (xmin + xmax)
            yc = 0.5 * (ymin + ymax)
            zc = 0.5 * (zmin + zmax)
            if a <= 1e-9:
                a, xc = r_eq, cx
            if b <= 1e-9:
                b, yc = r_eq, cy
            if c <= 1e-9:
                c, zc = r_eq, cz
            if 8.0 * a * b * c < vol * 0.99:
                xc, yc, zc, a, b, c = cx, cy, cz, r_eq, r_eq, r_eq
        else:
            xc, yc, zc, a, b, c = cx, cy, cz, r_eq, r_eq, r_eq

        pores.append((xc, yc, zc, a, b, c, vol))

    if not pores:
        return True

    def q1_unit_disk_rect_area(p0, q0, r0, s0):
        """Exact area of (u^2 + v^2 <= 1) intersected with [p0, q0] x [r0, s0], 0 <= p0 < q0, 0 <= r0 < s0."""
        if r0 >= 1.0 or p0 >= 1.0:
            return 0.0
        q_lim = math.sqrt(1.0 - r0 * r0)
        q = q_lim if q0 > q_lim else q0
        if p0 >= q:
            return 0.0
        u_s = math.sqrt(1.0 - s0 * s0) if s0 < 1.0 else 0.0
        area = 0.0
        if u_s > p0:
            u1 = q if q < u_s else u_s
            area += (u1 - p0) * (s0 - r0)
        u2 = p0 if p0 > u_s else u_s
        if q > u2:
            fq = 0.5 * (q * math.sqrt(max(0.0, 1.0 - q * q)) + math.asin(min(1.0, q)))
            fu2 = 0.5 * (u2 * math.sqrt(max(0.0, 1.0 - u2 * u2)) + math.asin(min(1.0, u2)))
            area += (fq - fu2) - r0 * (q - u2)
        return area

    def ellipse_rect_fraction(xc, yc, rx, ry, x0, x1, y0, y1):
        """Exact fraction of axis-aligned ellipse (xc, yc, rx, ry) inside [x0, x1] x [y0, y1]."""
        if rx <= 1e-12 or ry <= 1e-12:
            return 1.0 if (x0 <= xc <= x1 and y0 <= yc <= y1) else 0.0
        if xc + rx <= x0 or xc - rx >= x1 or yc + ry <= y0 or yc - ry >= y1:
            return 0.0
        if xc - rx >= x0 and xc + rx <= x1 and yc - ry >= y0 and yc + ry <= y1:
            return 1.0

        ux0 = (x0 - xc) / rx
        ux1 = (x1 - xc) / rx
        uy0 = (y0 - yc) / ry
        uy1 = (y1 - yc) / ry
        if ux0 < -1.0:
            ux0 = -1.0
        if ux1 > 1.0:
            ux1 = 1.0
        if uy0 < -1.0:
            uy0 = -1.0
        if uy1 > 1.0:
            uy1 = 1.0
        if ux0 >= ux1 or uy0 >= uy1:
            return 0.0

        x_segs = []
        if ux0 < 0.0:
            x_segs.append((0.0 if ux1 >= 0.0 else -ux1, -ux0))
        if ux1 > 0.0:
            x_segs.append((0.0 if ux0 <= 0.0 else ux0, ux1))

        y_segs = []
        if uy0 < 0.0:
            y_segs.append((0.0 if uy1 >= 0.0 else -uy1, -uy0))
        if uy1 > 0.0:
            y_segs.append((0.0 if uy0 <= 0.0 else uy0, uy1))

        total = 0.0
        for p0, q0 in x_segs:
            for r0, s0 in y_segs:
                total += q1_unit_disk_rect_area(p0, q0, r0, s0)
        return total / math.pi

    # Fast single-pore rejection check on orthogonal cross-sections.
    for xc, yc, zc, a, b, c, vol in pores:
        for r1, r2, r3 in ((a, b, c), (a, c, b), (b, c, a)):
            a_peak = min(0.75 * vol / r3, 4.0 * r1 * r2)
            if a_peak > LIMIT:
                if a_peak * ellipse_rect_fraction(0.0, 0.0, r1, r2, -HALF_WIN, HALF_WIN, -HALF_WIN, HALF_WIN) > LIMIT:
                    return False

    def eval_window_2d(pores_2d, x0, y0):
        x1 = x0 + WIN
        y1 = y0 + WIN
        total = 0.0
        for xc, yc, rx, ry, area in pores_2d:
            if xc + rx <= x0 or xc - rx >= x1 or yc + ry <= y0 or yc - ry >= y1:
                continue
            if xc - rx >= x0 and xc + rx <= x1 and yc - ry >= y0 and yc + ry <= y1:
                total += area
            else:
                total += area * ellipse_rect_fraction(xc, yc, rx, ry, x0, x1, y0, y1)
        return total

    def optimistic_max_2d(pores_2d):
        """Exact upper bound: full pore area counted if pore bbox touches [X, X+10] x [Y, Y+10]."""
        rects = []
        x_cands = set()
        for xc, yc, rx, ry, area in pores_2d:
            xlo = xc - rx - WIN
            xhi = xc + rx
            ylo = yc - ry - WIN
            yhi = yc + ry
            rects.append((xlo, xhi, ylo, yhi, area))
            x_cands.add(xlo)

        best = 0.0
        for x in x_cands:
            y_events = []
            x_sum = 0.0
            for xlo, xhi, ylo, yhi, area in rects:
                if xlo <= x <= xhi:
                    x_sum += area
                    y_events.append((ylo, 0, area))
                    y_events.append((yhi, 1, -area))
            if x_sum <= best:
                continue
            y_events.sort(key=lambda e: (e[0], e[1]))
            cur = 0.0
            for _, _, delta in y_events:
                cur += delta
                if cur > best:
                    best = cur
                    if best > LIMIT:
                        return best
        return best

    def make_1d_candidates(vals):
        vals.sort()
        dedup = []
        for v in vals:
            if not dedup or v - dedup[-1] > 1e-9:
                dedup.append(v)
        out = list(dedup)
        for i in range(len(dedup) - 1):
            gap = dedup[i + 1] - dedup[i]
            if 1e-6 < gap < 2.0:
                out.append(0.5 * (dedup[i] + dedup[i + 1]))
        return out

    def max_window_area_2d(pores_2d):
        """Return (max_area, best_x, best_y) for 10x10 window on a fixed slice."""
        if not pores_2d:
            return 0.0, 0.0, 0.0
        total_all = 0.0
        for p in pores_2d:
            total_all += p[4]
        if total_all <= LIMIT:
            return total_all, pores_2d[0][0] - HALF_WIN, pores_2d[0][1] - HALF_WIN

        if len(pores_2d) == 1:
            xc, yc, rx, ry, area = pores_2d[0]
            x0, y0 = xc - HALF_WIN, yc - HALF_WIN
            val = area * ellipse_rect_fraction(xc, yc, rx, ry, x0, x0 + WIN, y0, y0 + WIN)
            return val, x0, y0

        opt = optimistic_max_2d(pores_2d)
        if opt <= LIMIT:
            return opt, pores_2d[0][0] - HALF_WIN, pores_2d[0][1] - HALF_WIN

        xs_raw = []
        for xc, yc, rx, ry, area in pores_2d:
            xs_raw.append(xc - rx)
            xs_raw.append(xc + rx - WIN)
            if 2.0 * rx > WIN:
                xs_raw.append(xc - HALF_WIN)
        xs = make_1d_candidates(xs_raw)

        best_val = -1.0
        best_x = 0.0
        best_y = 0.0

        for x0 in xs:
            x1 = x0 + WIN
            x_active = []
            x_sum = 0.0
            for p in pores_2d:
                if p[0] + p[2] > x0 and p[0] - p[2] < x1:
                    x_active.append(p)
                    x_sum += p[4]
