            ys_raw = []
            for xc, yc, rx, ry, area in x_active:
                ys_raw.append(yc - ry)
                ys_raw.append(yc + ry - WIN)
                if 2.0 * ry > WIN:
                    ys_raw.append(yc - HALF_WIN)
            ys = make_1d_candidates(ys_raw)

            for y0 in ys:
                val = eval_window_2d(x_active, x0, y0)
                if val > best_val:
                    best_val = val
                    best_x = x0
                    best_y = y0
                    if best_val > LIMIT:
                        return best_val, best_x, best_y

        # Continuous local pattern-search refinement around best (x, y)
        step = 0.5
        while step >= 1e-4:
            improved = True
            while improved:
                improved = False
                for dx, dy in (
                    (step, 0.0), (-step, 0.0), (0.0, step), (0.0, -step),
                    (step, step), (step, -step), (-step, step), (-step, -step),
                ):
                    nx, ny = best_x + dx, best_y + dy
                    val = eval_window_2d(pores_2d, nx, ny)
                    if val > best_val + 1e-12:
