                        best_x = nx
                        best_y = ny
                        improved = True
                        if best_val > LIMIT:
                            return best_val, best_x, best_y
            step *= 0.5

        return best_val, best_x, best_y

    def build_slice_2d(proj, active, d):
        pores_2d = []
        for idx in active:
            d_c, h, a_max, a_cap, u_c, v_c, du_s, dv_s, ru_m, rv_m, _ = proj[idx]
            dd = d - d_c
            rel = dd / h
            f = 1.0 - rel * rel
            if f <= 0.0:
                continue
            area = a_max * f
            if area > a_cap:
                area = a_cap
            s = math.sqrt(f)
            pores_2d.append((u_c + dd * du_s, v_c + dd * dv_s, ru_m * s, rv_m * s, area))
        return pores_2d

    def check_block_sweep(proj, block_idxs):
        """Sweep along slice normal for a local set of pores; return False if > 1% found."""
        events = []
        for idx in block_idxs:
            d_c = proj[idx][0]
            h = proj[idx][1]
            events.append((d_c - h, 1, idx))
            events.append((d_c, 0, idx))
            events.append((d_c + h, -1, idx))
        events.sort(key=lambda e: e[0])

        active = set()
        active_peak_sum = 0.0
        n_ev = len(events)
        i = 0
        last_checked_d = None
        phi_inv = (math.sqrt(5.0) - 1.0) * 0.5

