        u_min = min(d[0] - d[2] for d in disks)
        u_max = max(d[0] + d[2] for d in disks)
        v_min = min(d[1] - d[2] for d in disks)
        v_max = max(d[1] + d[2] for d in disks)

        # Fast path: all disks fit completely inside one REF_SIDE x REF_SIDE square
        if u_max - u_min <= REF_SIDE + 1e-12 and v_max - v_min <= REF_SIDE + 1e-12:
            return True

        su_lo = u_min
        su_hi = max(u_min, u_max - REF_SIDE)
        sv_lo = v_min
        sv_hi = max(v_min, v_max - REF_SIDE)

        def eval_at(u0, v0, radii=None):
            total = 0.0
            if radii is None:
                for ru, rv, rd, _, _, _ in disks:
                    total += disk_rect_area(ru, rv, rd, u0, u0 + REF_SIDE, v0, v0 + REF_SIDE)
            else:
                for (ru, rv, _, _, _, _), rd in zip(disks, radii):
