        w_sum = sum(d[3] for d in disks)
        u_bar = sum(d[0] * d[3] for d in disks) / w_sum - 0.5 * REF_SIDE
        v_bar = sum(d[1] * d[3] for d in disks) / w_sum - 0.5 * REF_SIDE
        u_bar = min(su_hi, max(su_lo, u_bar))
        v_bar = min(sv_hi, max(sv_lo, v_bar))

        starts = [
            (u_bar, v_bar),
            (0.5 * (u_lo + u_hi), 0.5 * (v_lo + v_hi)),
            (su_lo, sv_lo),
            (su_hi, sv_lo),
            (su_lo, sv_hi),
            (su_hi, sv_hi),
        ]

        best_val = -1.0
        best_u, best_v = u_bar, v_bar
        for u0, v0 in starts:
            val = eval_at(u0, v0)
