```python
import math
from typing import Dict, List, Optional, Tuple

_WINDOW = 10.0          # 10 mm x 10 mm reference area
_LIMIT_AREA = 1.0       # 1% of 100 mm^2 = 1.0 mm^2
_EPS = 1e-9
_GRID_STEP = 5.0        # 3x3 block = 15 mm x 15 mm, guaranteed to contain any 10x10 window anchored in cell (iu, iv)
_INV_SQRT2 = 1.0 / math.sqrt(2.0)


def _F(u: float) -> float:
    """Antiderivative of sqrt(1 - u^2) for u in [-1, 1]."""
    return 0.5 * (u * math.sqrt(max(0.0, 1.0 - u * u)) + math.asin(u))


def _unit_disk_strip(u0: float, u1: float, h: float) -> float:
    """Area of {(u, v) : u in [u0, u1], 0 <= v <= min(h, sqrt(1 - u^2))}."""
    if h <= 0.0:
        return 0.0
    if u0 < -1.0:
        u0 = -1.0
    if u1 > 1.0:
        u1 = 1.0
    if u0 >= u1:
        return 0.0
    if h >= 1.0:
        return _F(u1) - _F(u0)
    c = math.sqrt(1.0 - h * h)
    area = 0.0
    if u0 < -c:
        hi = u1 if u1 < -c else -c
        area += _F(hi) - _F(u0)
    lo = u0 if u0 > -c else -c
    hi = u1 if u1 < c else c
    if lo < hi:
        area += h * (hi - lo)
    if u1 > c:
        lo = u0 if u0 > c else c
        area += _F(u1) - _F(lo)
    return area


def _unit_disk_rect(u0: float, u1: float, v0: float, v1: float) -> float:
    """Exact overlap area of the unit disk with axis-aligned rectangle [u0, u1] x [v0, v1]."""
    if u0 >= 1.0 or u1 <= -1.0 or v0 >= 1.0 or v1 <= -1.0:
        return 0.0
    if u0 <= -1.0 and u1 >= 1.0 and v0 <= -1.0 and v1 >= 1.0:
        return math.pi
    area = 0.0
    if v1 > 0.0:
        lo = v0 if v0 > 0.0 else 0.0
        if v1 > lo:
            area += _unit_disk_strip(u0, u1, v1) - _unit_disk_strip(u0, u1, lo)
    if v0 < 0.0:
        hi = -v0
        lo = -v1 if v1 < 0.0 else 0.0
        if hi > lo:
            area += _unit_disk_strip(u0, u1, hi) - _unit_disk_strip(u0, u1, lo)
    return area


def _ellipse_rect_overlap(
    cu: float, cv: float, a: float, b: float,
    u0: float, u1: float, v0: float, v1: float,
) -> float:
    """Exact overlap area of an axis-aligned ellipse with [u0, u1] x [v0, v1]."""
    if u0 >= cu + a or u1 <= cu - a or v0 >= cv + b or v1 <= cv - b:
        return 0.0
    if u0 <= cu - a and u1 >= cu + a and v0 <= cv - b and v1 >= cv + b:
        return math.pi * a * b
    return a * b * _unit_disk_rect(
        (u0 - cu) / a, (u1 - cu) / a,
        (v0 - cv) / b, (v1 - cv) / b,
    )


def _ellipse_strip_overlap(
    cu: float, a: float, b: float, u0: float, u1: float,
) -> float:
    """Exact overlap area of an axis-aligned ellipse with the vertical strip [u0, u1]."""
    if u0 >= cu + a or u1 <= cu - a:
        return 0.0
    if u0 <= cu - a and u1 >= cu + a:
        return math.pi * a * b
    x0 = (u0 - cu) / a
    x1 = (u1 - cu) / a
    if x0 < -1.0:
        x0 = -1.0
    if x1 > 1.0:
        x1 = 1.0
    return 2.0 * a * b * (_F(x1) - _F(x0))


def _dedup_sorted(vals: List[float], tol: float = 1e-7) -> List[float]:
    if not vals:
        return []
    vals.sort()
    out = [vals[0]]
    prev = vals[0]
    for v in vals[1:]:
        if v - prev > tol:
            out.append(v)
            prev = v
    return out


def _eval_window(
    ellipses: List[Tuple[int, float, float, float, float, float]],
    u0: float, v0: float,
) -> Tuple[float, List[int]]:
    u1 = u0 + _WINDOW
    v1 = v0 + _WINDOW
    total = 0.0
    ids: List[int] = []
    for pid, cu, cv, a, b, _ in ellipses:
        if cu + a > u0 and cu - a < u1 and cv + b > v0 and cv - b < v1:
            ov = _ellipse_rect_overlap(cu, cv, a, b, u0, u1, v0, v1)
            if ov > 0.0:
                total += ov
                ids.append(pid)
    return total, ids


def _golden_max_u(
    ellipses: List[Tuple[int, float, float, float, float, float]],
    lo: float, hi: float, v0: float, iters: int = 12,
) -> Tuple[float, float]:
    inv_phi = 0.6180339887498949
    c = hi - inv_phi * (hi - lo)
    d = lo + inv_phi * (hi - lo)
    fc, _ = _eval_window(ellipses, c, v0)
    fd, _ = _eval_window(ellipses, d, v0)
    for _ in range(iters):
        if fc < fd:
            lo = c
            c = d
            fc = fd
            d = lo + inv_phi * (hi - lo)
            fd, _ = _eval_window(ellipses, d, v0)
        else:
            hi = d
            d = c
            fd = fc
            c = hi - inv_phi * (hi - lo)
            fc, _ = _eval_window(ellipses, c, v0)
    if fc >= fd:
        return c, fc
    return d, fd


def _golden_max_v(
    ellipses: List[Tuple[int, float, float, float, float, float]],
    u0: float, lo: float, hi: float, iters: int = 12,
) -> Tuple[float, float]:
    inv_phi = 0.6180339887498949
    c = hi - inv_phi * (hi - lo)
    d = lo + inv_phi * (hi - lo)
    fc, _ = _eval_window(ellipses, u0, c)
    fd, _ = _eval_window(ellipses, u0, d)
    for _ in range(iters):
        if fc < fd:
            lo = c
            c = d
            fc = fd
            d = lo + inv_phi * (hi - lo)
            fd, _ = _eval_window(ellipses, u0, d)
        else:
            hi = d
            d = c
            fd = fc
            c = hi - inv_phi * (hi - lo)
            fc, _ = _eval_window(ellipses, u0, c)
    if fc >= fd:
        return c, fc
    return d, fd


def _max_window_area_2d(
    ellipses: List[Tuple[int, float, float, float, float, float]],
) -> Tuple[float, List[int]]:
    """
    Find maximum pore cross-sectional area inside any axis-aligned 10 mm x 10 mm window.
    Each ellipse is (pid, cu, cv, a, b, full_area).
    """
    if not ellipses:
        return 0.0, []

    total_area = sum(e[5] for e in ellipses)
    if total_area <= _LIMIT_AREA + _EPS:
        # Fast path: even if all ellipses fit in one window, limit cannot be exceeded.
        u_min = min(e[1] - e[3] for e in ellipses)
        u_max = max(e[1] + e[3] for e in ellipses)
        v_min = min(e[2] - e[4] for e in ellipses)
        v_max = max(e[2] + e[4] for e in ellipses)
        if u_max - u_min <= _WINDOW and v_max - v_min <= _WINDOW:
            return total_area, [e[0] for e in ellipses]
        # Still safe upper bound for Lipschitz skipping; no need for exact search if <= limit
        # unless we want a tighter bound for subsequent slices.
        return total_area, [e[0] for e in ellipses]

    u_min = min(e[1] - e[3] for e in ellipses)
    u_max = max(e[1] + e[3] for e in ellipses)
    v_min = min(e[2] - e[4] for e in ellipses)
    v_max = max(e[2] + e[4] for e in ellipses)
    if u_max - u_min <= _WINDOW and v_max - v_min <= _WINDOW:
        return total_area, [e[0] for e in ellipses]

    u_cands_raw: List[float] = []
    for _, cu, _, a, _, _ in ellipses:
        u_cands_raw.append(cu - a)
        u_cands_raw.append(cu + a - _WINDOW)
        u_cands_raw.append(cu)
        u_cands_raw.append(cu - _WINDOW)
    u_cands = _dedup_sorted(u_cands_raw)

    best_area = 0.0
    best_ids: List[int] = []
    # Keep up to 5 distinct high-value seeds for continuous coordinate refinement
    seeds: List[Tuple[float, float, float]] = []

    def _record_seed(area_val: float, su: float, sv: float) -> None:
        if area_val <= 0.5:
            return
        for idx, (sa, xu, xv) in enumerate(seeds):
            if abs(xu - su) < 0.5 and abs(xv - sv) < 0.5:
                if area_val > sa:
                    seeds[idx] = (area_val, su, sv)
                return
        if len(seeds) < 5:
            seeds.append((area_val, su, sv))
        else:
            min_idx = min(range(len(seeds)), key=lambda k: seeds[k][0])
            if area_val > seeds[min_idx][0]:
                seeds[min_idx] = (area_val, su, sv)

    for u0 in u_cands:
        u1 = u0 + _WINDOW
        strip = []
        strip_sum = 0.0
        sv_min = math.inf
        sv_max = -math.inf
        for e in ellipses:
            cu, cv, a, b = e[1], e[2], e[3], e[4]
            if cu + a > u0 and cu - a < u1:
                sa = _ellipse_strip_overlap(cu, a, b, u0, u1)
                if sa > 0.0:
                    strip.append(e)
                    strip_sum += sa
                    if cv - b < sv_min:
                        sv_min = cv - b
                    if cv + b > sv_max:
                        sv_max = cv + b

        if not strip:
            continue
        if strip_sum <= best_area and strip_sum <= 0.5:
            continue

        if sv_max - sv_min <= _WINDOW:
            if strip_sum > _LIMIT_AREA + _EPS:
                return strip_sum, [e[0] for e in strip]
            if strip_sum > best_area:
                best_area = strip_sum
                best_ids = [e[0] for e in strip]
            _record_seed(strip_sum, u0, sv_min)
            continue

        v_cands_raw: List[float] = []
        for _, _, cv, _, b, _ in strip:
            v_cands_raw.append(cv - b)
            v_cands_raw.append(cv + b - _WINDOW)
            v_cands_raw.append(cv)
            v_cands_raw.append(cv - _WINDOW)
        v_cands = _dedup_sorted(v_cands_raw)

        for v0 in v_cands:
            v1 = v0 + _WINDOW
            val = 0.0
            win_ids: List[int] = []
            for pid, cu, cv, a, b, _ in strip:
                if cv + b > v0 and cv - b < v1:
                    ov = _ellipse_rect_overlap(cu, cv, a, b, u0, u1, v0, v1)
                    if ov > 0.0:
                        val += ov
                        win_ids.append(pid)
            if val > _LIMIT_AREA + _EPS:
                return val, win_ids
            if val > best_area:
                best_area = val
                best_ids = win_ids
            _record_seed(val, u0, v0)

    if seeds:
        step_u = max(e[3] for e in ellipses)
        step_v = max(e[4] for e in ellipses)
        seeds.sort(key=lambda item: item[0], reverse=True)
        for _, su, sv in seeds:
            cur_u, cur_v = su, sv
            for _ in range(2):
                cur_u, cur_val = _golden_max_u(ellipses, cur_u - step_u, cur_u + step_u, cur_v)
                cur_v, cur_val = _golden_max_v(ellipses, cur_u, cur_v - step_v, cur_v + step_v)
            val, win_ids = _eval_window(ellipses, cur_u, cur_v)
            if val > _LIMIT_AREA + _EPS:
                return val, win_ids
            if val > best_area:
                best_area = val
                best_ids = win_ids

    return best_area, best_ids


def _extract_ellipsoids(pores: List[dict]) -> Optional[List[Tuple[float, float, float, float, float, float]]]:
    """
    Model each pore as an aspect-ratio-preserving equivalent-volume ellipsoid:
    (cx, cy, cz, rx, ry, rz) centered at centroid with volume == volume_mm3.
    Returns None immediately if a single pore already exceeds the 1% reference area limit.
    """
    ellipsoids: List[Tuple[float, float, float, float, float, float]] = []
    for pore in pores:
        vol = float(pore.get("volume_mm3", 0.0))
        if vol <= 0.0:
            continue
        cx, cy, cz = pore["centroid"]
        xmin, xmax, ymin, ymax, zmin, zmax = pore["bbox"]
        hx = 0.5 * (xmax - xmin)
        hy = 0.5 * (ymax - ymin)
        hz = 0.5 * (zmax - zmin)

        if hx > 0.0 and hy > 0.0 and hz > 0.0 and vol <= 8.0 * hx * hy * hz * (1.0 + 1e-6):
            v_ell = (4.0 / 3.0) * math.pi * hx * hy * hz
            scale = (vol / v_ell) ** (1.0 / 3.0)
            rx, ry, rz = hx * scale, hy * scale, hz * scale
        else:
            r = (3.0 * vol / (4.0 * math.pi)) ** (1.0 / 3.0)
            rx = ry = rz = r

        # Quick single-pore check on its three principal planes
        for a, b in ((rx, ry), (rx, rz), (ry, rz)):
            if math.pi * a * b > _LIMIT_AREA + _EPS:
                ov = _ellipse_rect_overlap(0.0, 0.0, a, b, -5.0, 5.0, -5.0, 5.0)
                if ov > _LIMIT_AREA + _EPS:
                    return None

        ellipsoids.append((float(cx), float(cy), float(cz), rx, ry, rz))
    return ellipsoids


def _project_for_orientation(
    ellipsoids: List[Tuple[float, float, float, float, float, float]],
    mode: int,
) -> List[Tuple[float, float, float, float, float, float, float, float, float]]:
    """
    Project 3D ellipsoids into a slice coordinate frame (u, v, w) where w is the slice normal.
    Modes 0..2: axis-aligned planes (XY, XZ, YZ).
    Modes 3..8: the 6 face-diagonal (45 deg) planes.
    Returns tuples: (cu, cv, cw, ru, rv, sigma_w, shift_slope, u_ext, a_max).
    """
    proj = []
    if mode < 3:
        if mode == 0:
            ui, vi, wi = 0, 1, 2
        elif mode == 1:
            ui, vi, wi = 0, 2, 1
        else:
            ui, vi, wi = 1, 2, 0
        for e in ellipsoids:
            cu, cv, cw = e[ui], e[vi], e[wi]
            ru, rv, rw = e[ui + 3], e[vi + 3], e[wi + 3]
            a_max = math.pi * ru * rv
            proj.append((cu, cv, cw, ru, rv, rw, 0.0, ru, a_max))
    else:
        configs = (
            (0, 1, 2, 1.0),
            (0, 1, 2, -1.0),
            (0, 2, 1, 1.0),
            (0, 2, 1, -1.0),
            (1, 2, 0, 1.0),
            (1, 2, 0, -1.0),
        )
        p, q, third, s = configs[mode - 3]
        for e in ellipsoids:
            cp, cq, c3 = e[p], e[q], e[third]
            rp, rq, r3 = e[p + 3], e[q + 3], e[third + 3]
            cw = (cp + s * cq) * _INV_SQRT2
            cu = (-s * cp + cq) * _INV_SQRT2
            cv = c3
            rp2 = rp * rp
            rq2 = rq * rq
            denom = rp2 + rq2
            sigma_w = math.sqrt(0.5 * denom)
            ru = math.sqrt(2.0 * rp2 * rq2 / denom)
            rv = r3
            shift_slope = s * (rq2 - rp2) / denom
            a_max = math.pi * ru * rv
            proj.append((cu, cv, cw, ru, rv, sigma_w, shift_slope, sigma_w, a_max))
    return proj


def _slice_area_of_pore(p: Tuple[float, ...], w: float) -> float:
    cw = p[2]
    sigma_w = p[5]
    dw = w - cw
    t = 1.0 - (dw * dw) / (sigma_w * sigma_w)
    if t <= 0.0:
        return 0.0
    return p[8] * t


def _eval_slice(
    proj: List[Tuple[float, ...]],
    active_ids: List[int],
    w: float,
    check_inplane_45: bool,
) -> Tuple[float, List[int], Dict[int, float]]:
    ellipses: List[Tuple[int, float, float, float, float, float]] = []
    areas: Dict[int, float] = {}
    for pid in active_ids:
        cu, cv, cw, ru, rv, sigma_w, shift_slope, _, a_max = proj[pid]
        dw = w - cw
        t = 1.0 - (dw * dw) / (sigma_w * sigma_w)
        if t <= 0.0:
            continue
        f = math.sqrt(t)
        area = a_max * t
        areas[pid] = area
        ellipses.append((pid, cu + shift_slope * dw, cv, ru * f, rv * f, area))

    best_val, win_ids = _max_window_area_2d(ellipses)
    if best_val > _LIMIT_AREA + _EPS:
        return best_val, win_ids, areas

    if check_inplane_45 and len(ellipses) > 1:
        ellipses_45 = []
        for pid, cu, cv, a, b, area in ellipses:
            u45 = (cu + cv) * _INV_SQRT2
            v45 = (-cu + cv) * _INV_SQRT2
            r_eq = math.sqrt(a * b)
            ellipses_45.append((pid, u45, v45, r_eq, r_eq, area))
        val45, ids45 = _max_window_area_2d(ellipses_45)
        if val45 > best_val:
            best_val = val45
            win_ids = ids45

    return best_val, win_ids, areas


def _peak_w_for_pores(
    proj: List[Tuple[float, ...]],
    pids: List[int],
    w_lo: float,
    w_hi: float,
) -> float:
    num = 0.0
    den = 0.0
    for pid in pids:
        p = proj[pid]
        cw = p[2]
        sigma_w = p[5]
        weight = p[8] / (sigma_w * sigma_w)
        num += weight * cw
        den += weight
    if den <= 0.0:
        return 0.5 * (w_lo + w_hi)
    w_star = num / den
    if w_star < w_lo:
        return w_lo
    if w_star > w_hi:
        return w_hi
    return w_star


def _check_column_w_sweep(
    proj: List[Tuple[float, ...]],
    col_pores: List[int],
    check_inplane_45: bool,
) -> bool:
    """Sweep slice position w across a 15 mm x 15 mm spatial column."""
    events: List[Tuple[float, int, int]] = []
    for pid in col_pores:
        cw = proj[pid][2]
        sigma_w = proj[pid][5]
        events.append((cw - sigma_w, 1, pid))  # enter
        events.append((cw, 2, pid))            # centroid peak
        events.append((cw + sigma_w, 0, pid))  # exit
    events.sort(key=lambda ev: (ev[0], ev[1]))

    active = set()
    running_a_max = 0.0
    last_w: Optional[float] = None
    last_best = 0.0
    last_areas: Dict[int, float] = {}

    n_events = len(events)
    idx = 0
    w_prev_ev: Optional[float] = None

    while idx < n_events:
        w_cur = events[idx][0]

        # Inspect elementary interval [w_prev_ev, w_cur] before applying events at w_cur
        if w_prev_ev is not None and w_cur > w_prev_ev + 1e-12 and active and running_a_max > _LIMIT_AREA - 1e-6:
            active_list = list(active)
            # No centroid lies strictly inside (w_prev_ev, w_cur), so every active pore's area
            # is monotonic on this interval; its max is at one of the two endpoints.
            ub_int = 0.0
            delta_ub = 0.0
            for pid in active_list:
                a0 = _slice_area_of_pore(proj[pid], w_prev_ev)
                a1 = _slice_area_of_pore(proj[pid], w_cur)
                am = a0 if a0 > a1 else a1
                ub_int += am
                if last_w is not None:
                    if proj[pid][6] == 0.0:
                        prev_a = last_areas.get(pid, 0.0)
                        if am > prev_a:
                            delta_ub += am - prev_a
                    else:
                        delta_ub += am

            if ub_int > _LIMIT_AREA + _EPS:
                if last_w is None or last_best + delta_ub > _LIMIT_AREA - 1e-3:
                    w_star = _peak_w_for_pores(proj, active_list, w_prev_ev, w_cur)
                    best_val, win_ids, areas = _eval_slice(proj, active_list, w_star, check_inplane_45)
                    if best_val > _LIMIT_AREA + _EPS:
                        return False
                    last_w = w_star
                    last_best = best_val
                    last_areas = areas

                    # Refine slice position specifically for the winning local window's pores
                    if win_ids and len(win_ids) < len(active_list) and best_val > 0.5:
                        w_win = _peak_w_for_pores(proj, win_ids, w_prev_ev, w_cur)
                        if abs(w_win - w_star) > 1e-6:
                            val_w, _, areas_w = _eval_slice(proj, active_list, w_win, check_inplane_45)
                            if val_w > _LIMIT_AREA + _EPS:
                                return False
                            if val_w > last_best:
                                last_w = w_win
                                last_best = val_w
                                last_areas = areas_w

        # Process all events at w_cur
        has_centroid = False
        while idx < n_events and events[idx][0] == w_cur:
            _, kind, pid = events[idx]
            if kind == 0:
                if pid in active:
                    active.remove(pid)
                    running_a_max -= proj[pid][8]
            elif kind == 1:
                active.add(pid)
                running_a_max += proj[pid][8]
            else:
                has_centroid = True
            idx += 1

        if not active:
            running_a_max = 0.0
            last_w = None
            last_best = 0.0
            last_areas = {}
        elif has_centroid and running_a_max > _LIMIT_AREA - 1e-6:
            active_list = list(active)
            # Recompute exact running_a_max occasionally to prevent floating-point drift
            running_a_max = sum(proj[pid][8] for pid in active_list)
            total_at_w = 0.0
            delta_ub = 0.0
            for pid in active_list:
                a_cur = _slice_area_of_pore(proj[pid], w_cur)
                total_at_w += a_cur
                if last_w is not None:
                    if proj[pid][6] == 0.0:
                        prev_a = last_areas.get(pid, 0.0)
                        if a_cur > prev_a:
                            delta_ub += a_cur - prev_a
                    else:
                        delta_ub += a_cur

            if total_at_w > _LIMIT_AREA + _EPS:
                if last_w is None or last_best + delta_ub > _LIMIT_AREA - 1e-3:
                    best_val, _, areas = _eval_slice(proj, active_list, w_cur, check_inplane_45)
                    if best_val > _LIMIT_AREA + _EPS:
                        return False
                    last_w = w_cur
                    last_best = best_val
                    last_areas = areas

        w_prev_ev = w_cur

    return True


def _check_orientation(
    ellipsoids: List[Tuple[float, float, float, float, float, float]],
    mode: int,
) -> bool:
    proj = _project_for_orientation(ellipsoids, mode)
    cells: Dict[Tuple[int, int], List[int]] = {}

    for pid, p in enumerate(proj):
        cu, cv, rv, u_ext = p[0], p[1], p[4], p[7]
        iu0 = math.floor((cu - u_ext) / _GRID_STEP)
        iu1 = math.floor((cu + u_ext) / _GRID_STEP)
        iv0 = math.floor((cv - rv) / _GRID_STEP)
        iv1 = math.floor((cv + rv) / _GRID_STEP)
        for iu in range(iu0, iu1 + 1):
            for iv in range(iv0, iv1 + 1):
                key = (iu, iv)
                bucket = cells.get(key)
                if bucket is None:
                    cells[key] = [pid]
                else:
                    bucket.append(pid)

    # Every 10 mm x 10 mm window anchored in cell (bu, bv) lies inside {bu..bu+2} x {bv..bv+2}
    candidate_blocks = set()
    for iu, iv in cells:
        for du in range(3):
            for dv in range(3):
                candidate_blocks.add((iu - du, iv - dv))

    check_inplane_45 = mode < 3
    for bu, bv in candidate_blocks:
        col_set = set()
        for du in range(3):
            for dv in range(3):
                bucket = cells.get((bu + du, bv + dv))
                if bucket is not None:
                    col_set.update(bucket)
        if not col_set:
            continue
        col_pores = list(col_set)
        if sum(proj[pid][8] for pid in col_pores) <= _LIMIT_AREA + _EPS:
            continue
        if not _check_column_w_sweep(proj, col_pores, check_inplane_45):
            return False

    return True


def check(part: dict) -> bool:
    """
    Verify that porosity does not exceed 1% in any 10 mm x 10 mm reference area.
    Returns True if the part is accepted, False otherwise.
    """
    pores = part.get("pores")
    if not pores:
        return True

    ellipsoids = _extract_ellipsoids(pores)
    if ellipsoids is None:
        return False
    if not ellipsoids:
        return True

    # Check the 3 orthogonal planes (XY, XZ, YZ, with 0 deg & 45 deg in-plane windows)
    # and the 6 face-diagonal (45 deg) planes.
    for mode in range(9):
        if not _check_orientation(ellipsoids, mode):
            return False

    return True
```

