def check(part):
    sealing_boxes = [
        zone["box"]
        for zone in part.get("zones", [])
        if zone.get("name") == "sealing"
    ]

    if not sealing_boxes:
        return True

    def point_in_box(point, box):
        x, y, z = point
        xmin, xmax, ymin, ymax, zmin, zmax = box
        return xmin <= x <= xmax and ymin <= y <= ymax and zmin <= z <= zmax

    def union_box_volume(boxes):
        if len(boxes) == 1:
            xmin, xmax, ymin, ymax, zmin, zmax = boxes[0]
            return max(0.0, xmax - xmin) * max(0.0, ymax - ymin) * max(0.0, zmax - zmin)

        xs = sorted({coord for b in boxes for coord in (b[0], b[1])})
        ys = sorted({coord for b in boxes for coord in (b[2], b[3])})

        total_vol = 0.0
        for i in range(len(xs) - 1):
            x0, x1 = xs[i], xs[i + 1]
            if x1 <= x0:
                continue
            x_boxes = [b for b in boxes if b[0] <= x0 and b[1] >= x1]
            if not x_boxes:
                continue
            dx = x1 - x0
            for j in range(len(ys) - 1):
                y0, y1 = ys[j], ys[j + 1]
                if y1 <= y0:
                    continue
                xy_boxes = [b for b in x_boxes if b[2] <= y0 and b[3] >= y1]
                if not xy_boxes:
                    continue
                dy = y1 - y0
                z_intervals = sorted((b[4], b[5]) for b in xy_boxes if b[5] > b[4])
                if not z_intervals:
                    continue
                dz_total = 0.0
                cur_z0, cur_z1 = z_intervals[0]
                for z0, z1 in z_intervals[1:]:
                    if z0 <= cur_z1:
                        if z1 > cur_z1:
                            cur_z1 = z1
                    else:
                        dz_total += cur_z1 - cur_z0
                        cur_z0, cur_z1 = z0, z1
                dz_total += cur_z1 - cur_z0
                total_vol += dx * dy * dz_total
        return total_vol

    sealing_pore_volume = sum(
        pore["volume_mm3"]
        for pore in part.get("pores", [])
        if any(point_in_box(pore["centroid"], box) for box in sealing_boxes)
    )

    sealing_zone_volume = union_box_volume(sealing_boxes)
    if sealing_zone_volume <= 0.0:
        return sealing_pore_volume == 0.0

    porosity = sealing_pore_volume / sealing_zone_volume
    return porosity <= 0.002
```

