        xmin, xmax, ymin, ymax, zmin, zmax = box
        return xmin <= x <= xmax and ymin <= y <= ymax and zmin <= z <= zmax

    def _union_volume(boxes):
        valid = [
            b for b in boxes
            if b[0] < b[1] and b[2] < b[3] and b[4] < b[5]
        ]
        if not valid:
