            for j in range(len(ys) - 1):
                y0, y1 = ys[j], ys[j + 1]
                dy = y1 - y0
                if dy <= 0.0:
                    continue
                xy_boxes = [b for b in x_boxes if b[2] <= y0 and b[3] >= y1]
                if not xy_boxes:
                    continue
                intervals = sorted((b[4], b[5]) for b in xy_boxes)
                z_len = 0.0
                cur_start, cur_end = intervals[0]
                for start, end in intervals[1:]:
                    if start <= cur_end:
                        if end > cur_end:
                            cur_end = end
                    else:
                        z_len += cur_end - cur_start
                        cur_start, cur_end = start, end
                z_len += cur_end - cur_start
                total += dx * dy * z_len
        return total

    sealing_pore_volume = 0.0
    for pore in part.get("pores", []):
        if any(_point_in_box(pore["centroid"], box) for box in sealing_boxes):
            sealing_pore_volume += pore["volume_mm3"]

    sealing_volume = _union_volume(sealing_boxes)
    if sealing_volume <= 0.0:
