```python
import math


def check(part):
    sealing_boxes = [
        zone["box"]
        for zone in part.get("zones", [])
        if zone["name"] == "sealing"
    ]
    if not sealing_boxes:
        return True

    def boxes_union_volume(boxes):
        valid = [
            b for b in boxes
            if b[1] > b[0] and b[3] > b[2] and b[5] > b[4]
        ]
        if not valid:
            return 0.0
        if len(valid) == 1:
            x0, x1, y0, y1, z0, z1 = valid[0]
            return (x1 - x0) * (y1 - y0) * (z1 - z0)

        xs = sorted({b[0] for b in valid} | {b[1] for b in valid})
        ys = sorted({b[2] for b in valid} | {b[3] for b in valid})
        zs = sorted({b[4] for b in valid} | {b[5] for b in valid})

        total = 0.0
        for i in range(len(xs) - 1):
            x0, x1 = xs[i], xs[i + 1]
            dx = x1 - x0
            x_boxes = [b for b in valid if b[0] <= x0 and x1 <= b[1]]
            if not x_boxes:
                continue
            for j in range(len(ys) - 1):
                y0, y1 = ys[j], ys[j + 1]
                dy = y1 - y0
                xy_boxes = [b for b in x_boxes if b[2] <= y0 and y1 <= b[3]]
                if not xy_boxes:
                    continue
                for k in range(len(zs) - 1):
                    z0, z1 = zs[k], zs[k + 1]
                    if any(b[4] <= z0 and z1 <= b[5] for b in xy_boxes):
                        total += dx * dy * (z1 - z0)
        return total

    pore_volumes = []
    for pore in part.get("pores", []):
        x, y, z = pore["centroid"]
        if any(
            xmin <= x <= xmax and ymin <= y <= ymax and zmin <= z <= zmax
            for xmin, xmax, ymin, ymax, zmin, zmax in sealing_boxes
        ):
            pore_volumes.append(pore["volume_mm3"])

    total_pore_volume = math.fsum(pore_volumes)
    zone_volume = boxes_union_volume(sealing_boxes)

    if zone_volume <= 0.0:
        return total_pore_volume <= 0.0

    return (total_pore_volume / zone_volume) <= 0.002
```

ASSUMPTIONS:
- Porosity in the sealing zone is defined as the total volume of pores in the sealing zone divided by the geometric volume of the sealing zone box (not `part_volume_mm3`), since the part's exact material volume intersecting the box is not provided.
- A pore is assigned to the sealing zone if its `centroid` lies inside or on the boundary (`<=`) of a `'sealing'` zone box, contributing its full `volume_mm3` (rather than using `bbox` intersection or partial-volume clipping).
- Zone name matching for `'sealing'` is exact and case-sensitive.
- If multiple zones are named `'sealing'`, they are treated together as a single combined sealing zone using the geometric union of their boxes (avoiding double-counting overlapping zone volumes or pores).
- "Must not exceed 0.2%" is interpreted as an inclusive threshold (`total_pore_volume / zone_volume <= 0.002`).
- All pores in the sealing zone are counted regardless of size, sphericity, or whether they are open to the surface (`dist_surface_mm == 0`), and individual pores are assumed to be non-overlapping.
- If a `'sealing'` zone has zero volume (degenerate box), the check accepts if total pore volume in the zone is 0 and rejects if it is positive.

