def check(part):
    """Return True if no pore with equivalent diameter above 0.20 mm is in the sealing zone."""
    def _is_sealing_zone(name):
        normalized = " ".join(
            name.strip().lower().replace("_", " ").replace("-", " ").split()
        )
        return normalized in {"sealing", "sealing zone"}

    def _pore_in_box(pore, box):
        z_xmin, z_xmax, z_ymin, z_ymax, z_zmin, z_zmax = box
        cx, cy, cz = pore["centroid"]
        if (
            z_xmin <= cx <= z_xmax
            and z_ymin <= cy <= z_ymax
            and z_zmin <= cz <= z_zmax
        ):
            return True
        bbox = pore.get("bbox")
        if bbox is not None:
            p_xmin, p_xmax, p_ymin, p_ymax, p_zmin, p_zmax = bbox
            return (
                p_xmin < z_xmax
                and p_xmax > z_xmin
                and p_ymin < z_ymax
                and p_ymax > z_ymin
                and p_zmin < z_zmax
                and p_zmax > z_zmin
            )
        return False

    sealing_boxes = [
        zone["box"]
        for zone in part.get("zones", [])
        if _is_sealing_zone(zone["name"])
    ]
    if not sealing_boxes:
        return True

    for pore in part.get("pores", []):
        if pore["d_eq_mm"] > 0.20:
            if any(_pore_in_box(pore, box) for box in sealing_boxes):
                return False

    return True
