This criterion cannot be implemented as an authoritative pass/fail check as written because **"clustered porosity" is not quantitatively defined**. Standards (e.g., ASTM E155, AMS 2175, ASME BPVC, AWS D17.1, ISO 10042) define porosity clusters very differently, so hardcoding guessed thresholds would risk accepting defective parts or rejecting conforming ones.

Before deploying this check, please confirm the governing specification's definitions for:

1. **Cluster definition & pore count:**
   - What is the minimum number of pores that constitutes a cluster (e.g., $\ge 3$, $\ge 4$, or $\ge 5$)?
   - Is a cluster defined by **pairwise proximity** (a connected group of pores within a spacing limit) or by **density within a fixed region** (e.g., $N$ or more pores inside a sphere/cube of a given size, or local porosity % within a sub-volume)?
2. **Spacing metric & threshold:**
   - Is the spacing limit a **fixed distance** (in mm), a **multiple of pore diameter** (e.g., $\le k \times d$ of the smaller, larger, or summed pair using `d_eq_mm` or `feret_max_mm`), or tied to **`wall_mm` / `nominal_wall_mm`**?
   - Because `part["pores"]` does not include exact 3D surface meshes, exact surface-to-surface spacing cannot be computed—should spacing be approximated using **centroid distance**, **axis-aligned `bbox` gap**, or **equivalent-sphere gap** (`dist(c1, c2) - (d1 + d2)/2`)?
3. **Pore filtering:**
   - Is there a minimum pore size cutoff (`d_eq_mm`, `feret_max_mm`, or `volume_mm3`) below which pores are ignored?
   - Does the rule apply to all pores, or only specific types/locations (e.g., gas vs. shrinkage via `sphericity`, or near-surface pores via `dist_surface_mm`)?
4. **Inspection scope:**
   - Does the rule apply to the entire part or only to specific `part["zones"]`?

Below is a standard-library implementation for pairwise-linked clustering that **fails safely** (`ValueError`) until the specification's quantitative parameters are explicitly provided. Once you confirm the governing numbers (or if your spec uses a fixed-window density rule instead of pairwise linkage), we can lock them into `check(part)`.

```python
import math
from typing import Any, Dict, Optional


def check(
    part: Dict[str, Any],
    *,
    min_cluster_pores: Optional[int] = None,
    distance_mode: Optional[str] = None,  # "centroid", "bbox_gap", or "equiv_sphere_gap"
    max_gap_mm: Optional[float] = None,
    max_gap_diameter_ratio: Optional[float] = None,
    diameter_field: str = "d_eq_mm",      # "d_eq_mm" or "feret_max_mm"
    diameter_ref: str = "max",            # "min", "max", or "sum"
    min_pore_d_eq_mm: float = 0.0,
) -> bool:
    """Return True to accept (no cluster found), False to reject (cluster found).

    Raises ValueError if required quantitative cluster parameters from the
    governing inspection specification have not been configured.
    """
    if min_cluster_pores is None or min_cluster_pores < 2:
        raise ValueError(
            "Specification parameter 'min_cluster_pores' (>= 2) must be set "
            "before evaluating clustered porosity."
        )
    if distance_mode not in ("centroid", "bbox_gap", "equiv_sphere_gap"):
        raise ValueError(
            "Specification parameter 'distance_mode' must be one of "
            "'centroid', 'bbox_gap', or 'equiv_sphere_gap'."
        )
    if (max_gap_mm is None) == (max_gap_diameter_ratio is None):
        raise ValueError(
            "Specify exactly one spacing rule: 'max_gap_mm' OR 'max_gap_diameter_ratio'."
        )
    if max_gap_mm is not None and max_gap_mm < 0.0:
        raise ValueError("'max_gap_mm' must be non-negative.")
    if max_gap_diameter_ratio is not None:
        if max_gap_diameter_ratio < 0.0:
            raise ValueError("'max_gap_diameter_ratio' must be non-negative.")
        if diameter_field not in ("d_eq_mm", "feret_max_mm"):
            raise ValueError("'diameter_field' must be 'd_eq_mm' or 'feret_max_mm'.")
        if diameter_ref not in ("min", "max", "sum"):
            raise ValueError("'diameter_ref' must be 'min', 'max', or 'sum'.")

    pores = [
        p for p in part.get("pores", [])
        if p["d_eq_mm"] >= min_pore_d_eq_mm
    ]
    n = len(pores)
    if n < min_cluster_pores:
        return True

    def pair_distance(p1: Dict[str, Any], p2: Dict[str, Any]) -> float:
        if distance_mode == "centroid":
            return math.dist(p1["centroid"], p2["centroid"])
        if distance_mode == "equiv_sphere_gap":
            center_dist = math.dist(p1["centroid"], p2["centroid"])
            return max(0.0, center_dist - 0.5 * (p1["d_eq_mm"] + p2["d_eq_mm"]))
        # distance_mode == "bbox_gap"
        b1, b2 = p1["bbox"], p2["bbox"]
        dx = max(0.0, b1[0] - b2[1], b2[0] - b1[1])
        dy = max(0.0, b1[2] - b2[3], b2[2] - b1[3])
        dz = max(0.0, b1[4] - b2[5], b2[4] - b1[5])
        return math.sqrt(dx * dx + dy * dy + dz * dz)

    def pair_threshold(p1: Dict[str, Any], p2: Dict[str, Any]) -> float:
        if max_gap_mm is not None:
            return max_gap_mm
        d1, d2 = p1[diameter_field], p2[diameter_field]
        if diameter_ref == "min":
            ref_d = min(d1, d2)
        elif diameter_ref == "max":
            ref_d = max(d1, d2)
        else:
            ref_d = d1 + d2
        return max_gap_diameter_ratio * ref_d  # type: ignore[operator]

    # Disjoint-set union to find connected clusters of linked pores
    parent = list(range(n))
    size = [1] * n

    def find(i: int) -> int:
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(i: int, j: int) -> int:
        ri, rj = find(i), find(j)
        if ri == rj:
            return size[ri]
        if size[ri] < size[rj]:
            ri, rj = rj, ri
        parent[rj] = ri
        size[ri] += size[rj]
        return size[ri]

    for i in range(n):
        p1 = pores[i]
        for j in range(i + 1, n):
            p2 = pores[j]
            if pair_distance(p1, p2) <= pair_threshold(p1, p2):
                if union(i, j) >= min_cluster_pores:
                    return False

    return True
