import math


def _point_in_box(point, box) -> bool:
    x, y, z = point
    xmin, xmax, ymin, ymax, zmin, zmax = box
    return xmin <= x <= xmax and ymin <= y <= ymax and zmin <= z <= zmax


def _boxes_union_volume(boxes) -> float:
    valid = [
        b for b in boxes
        if b[1] > b[0] and b[3] > b[2] and b[5] > b[4]
    ]
    if not valid:
        return 0.0
    if len(valid) == 1:
        xmin, xmax, ymin, ymax, zmin, zmax = valid[0]
        return (xmax - xmin) * (ymax - ymin) * (zmax - zmin)

    xs = sorted({x for b in valid for x in (b[0], b[1])})
    total_vol = 0.0
    for i in range(len(xs) - 1):
        x0, x1 = xs[i], xs[i + 1]
        dx = x1 - x0
        if dx <= 0.0:
            continue
        x_boxes = [b for b in valid if b[0] <= x0 and b[1] >= x1]
        if not x_boxes:
            continue
        ys = sorted({y for b in x_boxes for y in (b[2], b[3])})
        area_yz = 0.0
        for j in range(len(ys) - 1):
            y0, y1 = ys[j], ys[j + 1]
            dy = y1 - y0
            if dy <= 0.0:
                continue
            z_intervals = sorted(
                (b[4], b[5]) for b in x_boxes if b[2] <= y0 and b[3] >= y1
            )
            if not z_intervals:
                continue
            z_len = 0.0
            cur_start, cur_end = z_intervals[0]
            for zs, ze in z_intervals[1:]:
                if zs <= cur_end:
                    if ze > cur_end:
                        cur_end = ze
                else:
                    z_len += cur_end - cur_start
                    cur_start, cur_end = zs, ze
            z_len += cur_end - cur_start
            area_yz += dy * z_len
        total_vol += dx * area_yz
    return total_vol


def check(part) -> bool:
    """Return True if porosity in the 'sealing' zone does not exceed 0.2%."""
    sealing_boxes = [
        z["box"] for z in part.get("zones", []) if z.get("name") == "sealing"
    ]
    if not sealing_boxes:
        return True

    pore_vol = math.fsum(
        p["volume_mm3"]
        for p in part.get("pores", [])
        if any(_point_in_box(p["centroid"], box) for box in sealing_boxes)
    )
    if pore_vol <= 0.0:
        return True

    zone_vol = _boxes_union_volume(sealing_boxes)
    if zone_vol <= 0.0:
        return False

    porosity = pore_vol / zone_vol
    limit = 0.002  # 0.2%
    return porosity <= limit or math.isclose(porosity, limit, rel_tol=1e-12, abs_tol=0.0)
