import math


def _has_cluster_violation(points, box_size, max_pores, tol):
    """Return True if any axis-aligned cube of side `box_size` contains more than `max_pores` points."""
    limit = max_pores + 1
    n = len(points)
    if n < limit:
        return False

    pts_x = sorted(points, key=lambda p: p[0])
    j = 0
    prev_j = -1
    for i in range(n):
        x0 = pts_x[i][0]
        while j < n and pts_x[j][0] - x0 <= tol:
            j += 1
        if j > prev_j and j - i >= limit:
            prev_j = j
            pts_y = sorted(pts_x[i:j], key=lambda p: p[1])
            m = len(pts_y)
            yj = 0
            prev_yj = -1
            for yi in range(m):
                y0 = pts_y[yi][1]
                while yj < m and pts_y[yj][1] - y0 <= tol:
                    yj += 1
                if yj > prev_yj and yj - yi >= limit:
                    prev_yj = yj
                    zs = sorted(p[2] for p in pts_y[yi:yj])
                    for k in range(len(zs) - limit + 1):
                        if zs[k + limit - 1] - zs[k] <= tol:
                            return True
                if yj == m:
                    break
        if j == n:
            break
    return False


def check(part):
    """Return True if no 5 mm x 5 mm x 5 mm reference volume contains more than 3 pores with d_eq >= 0.15 mm."""
    min_d_eq = 0.15
    box_size = 5.0
    max_pores = 3
    limit = max_pores + 1
    tol = box_size + 1e-12

    qualifying = [
        tuple(pore["centroid"])
        for pore in part.get("pores", [])
        if pore["d_eq_mm"] >= min_d_eq
    ]
    if len(qualifying) < limit:
        return True

    # Spatial hash with cell size slightly larger than box_size so any cluster
    # fitting in a box_size cube spans at most adjacent cells (dx in {0, 1},
    # dy in {-1, 0, 1}, dz in {-1, 0, 1} relative to its minimum-x pore's cell).
    cell_size = box_size + 1e-4
    grid = {}
    for pt in qualifying:
        key = (
            math.floor(pt[0] / cell_size),
            math.floor(pt[1] / cell_size),
            math.floor(pt[2] / cell_size),
        )
        grid.setdefault(key, []).append(pt)

    # Fast check within individual cells first.
    for pts in grid.values():
        if len(pts) >= limit and _has_cluster_violation(pts, box_size, max_pores, tol):
            return False

    # Check clusters spanning across cell boundaries.
    for (cx, cy, cz), pts in grid.items():
        local_pts = []
        for dx in (0, 1):
            nx = cx + dx
            for dy in (-1, 0, 1):
                ny = cy + dy
                for dz in (-1, 0, 1):
                    cell_pts = grid.get((nx, ny, cz + dz))
                    if cell_pts is not None:
                        local_pts.extend(cell_pts)
        if len(local_pts) > len(pts) and len(local_pts) >= limit:
            if _has_cluster_violation(local_pts, box_size, max_pores, tol):
                return False

    return True
