Here is an implementation of `check(part)` that evaluates the criterion using an exact sliding axis-aligned 5 mm × 5 mm × 5 mm reference volume check over all qualifying pores (`d_eq_mm >= 0.15`), accelerated with a spatial hash grid for linear-time performance:

```python
import math


def check(part):
    min_d_eq = 0.15
    ref_size = 5.0
    max_pores = 3
    limit = ref_size + 1e-12

    points = [
        (p["centroid"][0], p["centroid"][1], p["centroid"][2])
        for p in part["pores"]
        if p["d_eq_mm"] >= min_d_eq
    ]

    if len(points) <= max_pores:
        return True

    def has_violation(pts):
        n = len(pts)
        if n <= max_pores:
            return False

        pts_x = sorted(pts, key=lambda p: p[0])
        j = 0
        prev_j = -1
        for i in range(n - max_pores):
            x_limit = pts_x[i][0] + limit
            while j < n and pts_x[j][0] <= x_limit:
                j += 1
            if j == prev_j:
                continue
            prev_j = j
            if j - i <= max_pores:
                continue

            pts_y = sorted(pts_x[i:j], key=lambda p: p[1])
            m = len(pts_y)
            b = 0
            prev_b = -1
            for a in range(m - max_pores):
                y_limit = pts_y[a][1] + limit
                while b < m and pts_y[b][1] <= y_limit:
                    b += 1
                if b == prev_b:
                    continue
                prev_b = b
                if b - a <= max_pores:
                    continue

                zs = sorted(p[2] for p in pts_y[a:b])
                for c in range(len(zs) - max_pores):
                    if zs[c + max_pores] - zs[c] <= limit:
                        return True
        return False

    # Partition space into cells slightly larger than ref_size so any 5x5x5 cube
    # is guaranteed to lie entirely within a 2x2x2 block of grid cells.
    cell_size = ref_size + 1e-3
    cells = {}
    for pt in points:
        key = (
            math.floor(pt[0] / cell_size),
            math.floor(pt[1] / cell_size),
            math.floor(pt[2] / cell_size),
        )
        if key in cells:
            cells[key].append(pt)
        else:
            cells[key] = [pt]

    # Check single cells first so every surviving cell has bounded occupancy.
    for cell_pts in cells.values():
        if len(cell_pts) > max_pores and has_violation(cell_pts):
            return False

    # Check every 2x2x2 block of cells containing pores from multiple cells.
    anchors = set()
    for cx, cy, cz in cells:
        for dx in (0, 1):
            for dy in (0, 1):
                for dz in (0, 1):
                    anchors.add((cx - dx, cy - dy, cz - dz))

    for ax, ay, az in anchors:
        block_pts = []
        occupied_in_block = 0
        for dx in (0, 1):
            for dy in (0, 1):
                for dz in (0, 1):
                    cpts = cells.get((ax + dx, ay + dy, az + dz))
                    if cpts:
                        occupied_in_block += 1
                        block_pts.extend(cpts)
        if occupied_in_block > 1 and len(block_pts) > max_pores and has_violation(block_pts):
            return False

    return True
