from collections import defaultdict


def _has_2d_cluster(pts, limit, k):
    n = len(pts)
    pts.sort(key=lambda p: p[1])

    j = 0
    prev_j = 0
    for i in range(n - k + 1):
        y_i = pts[i][1]
        while j < n and pts[j][1] - y_i <= limit:
            j += 1
        if j - i >= k and j > prev_j:
            prev_j = j
            zs = sorted(p[2] for p in pts[i:j])
            for m in range(len(zs) - k + 1):
                if zs[m + k - 1] - zs[m] <= limit:
                    return True
        if j == n:
            break
    return False


def _has_3d_cluster(pts, limit, k):
    n = len(pts)
    if n < k:
        return False
    pts.sort(key=lambda p: p[0])

    j = 0
    prev_j = 0
    for i in range(n - k + 1):
        x_i = pts[i][0]
        while j < n and pts[j][0] - x_i <= limit:
            j += 1
        if j - i >= k and j > prev_j:
            prev_j = j
            if _has_2d_cluster(pts[i:j], limit, k):
                return True
        if j == n:
            break
    return False


def check(part) -> bool:
    """Return True if every 5 mm x 5 mm x 5 mm axis-aligned reference volume
    contains at most 3 pores with equivalent diameter >= 0.15 mm.
    """
    min_d_eq_mm = 0.15
    ref_size_mm = 5.0
    max_pores = 3
    eps = 1e-9
    limit = ref_size_mm + eps

    pts = [
        (float(p["centroid"][0]), float(p["centroid"][1]), float(p["centroid"][2]))
        for p in part["pores"]
        if p["d_eq_mm"] >= min_d_eq_mm
    ]

    if len(pts) <= max_pores:
        return True

    # Partition space into 4 mm sub-cells and 8 mm coarse cells:
    # - Any 4 x 4 x 4 mm cell fits completely inside a 5 x 5 x 5 mm cube,
    #   so >3 qualifying pores in one 4 mm cell immediately rejects the part.
    # - Otherwise each 8 mm cell has <= 8 * 3 = 24 pores, and because
    #   5.0 / 8.0 < 1, any 5 x 5 x 5 mm cube lies entirely within a single
    #   2 x 2 x 2 block of 8 mm cells.
    small_counts = defaultdict(int)
    big_cells = defaultdict(list)

    for x, y, z in pts:
        sx = math.floor(x / 4.0)
        sy = math.floor(y / 4.0)
        sz = math.floor(z / 4.0)
        sk = (sx, sy, sz)
        small_counts[sk] += 1
        if small_counts[sk] > max_pores:
            return False
        big_cells[(sx >> 1, sy >> 1, sz >> 1)].append((x, y, z))

    block_counts = defaultdict(int)
    for (bx, by, bz), cell_pts in big_cells.items():
        cnt = len(cell_pts)
        for dx in (0, 1):
            ax = bx - dx
            for dy in (0, 1):
                ay = by - dy
                for dz in (0, 1):
                    block_counts[(ax, ay, bz - dz)] += cnt

    k = max_pores + 1
    for (ax, ay, az), total in block_counts.items():
        if total < k:
            continue
        block_pts = []
        for dx in (0, 1):
            bx = ax + dx
            for dy in (0, 1):
                by = ay + dy
                for dz in (0, 1):
                    cell = big_cells.get((bx, by, az + dz))
                    if cell:
                        block_pts.extend(cell)
        if _has_3d_cluster(block_pts, limit, k):
            return False

    return True
