import math


def check(part):
    """Return True if at most 3 pores with d_eq_mm >= 0.15 mm lie in any 5x5x5 mm cube."""
    min_d_eq_mm = 0.15
    ref_size_mm = 5.0
    max_pores = 3
    eps = 1e-12

    def has_violating_box(points):
        limit = ref_size_mm + eps
        min_violation = max_pores + 1
        n = len(points)
        if n < min_violation:
            return False

        pts_x = sorted(points, key=lambda p: p[0])
        right_x = 0
        prev_right_x = 0

        for left_x in range(n):
            x_start = pts_x[left_x][0]
            while right_x < n and pts_x[right_x][0] - x_start <= limit:
                right_x += 1

            if right_x == prev_right_x:
                continue
            prev_right_x = right_x

            if right_x - left_x < min_violation:
                continue

            pts_y = sorted(pts_x[left_x:right_x], key=lambda p: p[1])
            ny = len(pts_y)
            right_y = 0
            prev_right_y = 0

            for left_y in range(ny):
                y_start = pts_y[left_y][1]
                while right_y < ny and pts_y[right_y][1] - y_start <= limit:
                    right_y += 1

                if right_y == prev_right_y:
                    continue
                prev_right_y = right_y

                if right_y - left_y < min_violation:
                    continue

                zs = sorted(p[2] for p in pts_y[left_y:right_y])
                for i in range(len(zs) - max_pores):
                    if zs[i + max_pores] - zs[i] <= limit:
                        return True

        return False

    qualifying = [
        tuple(pore["centroid"])
        for pore in part["pores"]
        if pore["d_eq_mm"] >= min_d_eq_mm
    ]

