    # box is fully contained in some 2x2x2 block of cells, with margin against float rounding.
    cell_size = ref_size_mm * 1.1  # 5.5 mm
    # Any 5.5 mm cube can be split into eight 2.75 mm sub-cubes (< 5.0 mm);
    # > 8 * max_pores points in a single cell guarantees a violation.
    pigeonhole_limit = 8 * max_pores + 1

    grid = {}
    for pt in qualifying:
        key = (
            math.floor(pt[0] / cell_size),
            math.floor(pt[1] / cell_size),
            math.floor(pt[2] / cell_size),
        )
        bucket = grid.get(key)
        if bucket is None:
            grid[key] = [pt]
        else:
            bucket.append(pt)
            if len(bucket) >= pigeonhole_limit and has_violating_box(bucket):
                return False

    anchors = set()
    for cx, cy, cz in grid:
