from collections import defaultdict


def check(part) -> bool:
    min_d_eq = 0.15
    ref_size = 5.0
    max_pores = 3
    tol = 1e-12
    limit = ref_size + tol

    points = [
        tuple(pore["centroid"])
        for pore in part["pores"]
        if pore["d_eq_mm"] >= min_d_eq
    ]
    if len(points) <= max_pores:
        return True

    # Spatial hashing with cell_size > limit guarantees that any set of pores
    # fitting in an axis-aligned 5x5x5 cube lies within one 2x2x2 block of cells.
    cell_size = ref_size + 0.5
    grid = defaultdict(list)
    for pt in points:
        key = (
            math.floor(pt[0] / cell_size),
            math.floor(pt[1] / cell_size),
            math.floor(pt[2] / cell_size),
        )
        cell = grid[key]
        cell.append(pt)
        # A 5.5x5.5x5.5 cell is covered by 8 sub-cubes of side 2.75 < 5.0.
        if len(cell) > 8 * max_pores:
            return False

    candidates = set()
    for cx, cy, cz in grid:
        for dx in (0, 1):
            for dy in (0, 1):
                for dz in (0, 1):
                    candidates.add((cx - dx, cy - dy, cz - dz))

    for gx, gy, gz in candidates:
        block = []
        for dx in (0, 1):
            for dy in (0, 1):
                for dz in (0, 1):
                    cell = grid.get((gx + dx, gy + dy, gz + dz))
                    if cell:
                        block.extend(cell)

        n = len(block)
        if n <= max_pores:
            continue
        # An 11x11x11 block is covered by 27 sub-cubes of side 11/3 < 5.0.
        if n > 27 * max_pores:
            return False

        block.sort(key=lambda p: p[0])
        for i in range(n - max_pores):
            if i > 0 and block[i][0] == block[i - 1][0]:
                continue
            x_end = block[i][0] + limit
            r_x = i + 1
            while r_x < n and block[r_x][0] <= x_end:
                r_x += 1
            if r_x - i <= max_pores:
                continue

            wx = block[i:r_x]
            wx.sort(key=lambda p: p[1])
            m = len(wx)
            for j in range(m - max_pores):
                if j > 0 and wx[j][1] == wx[j - 1][1]:
                    continue
                y_end = wx[j][1] + limit
                r_y = j + 1
                while r_y < m and wx[r_y][1] <= y_end:
                    r_y += 1
                if r_y - j <= max_pores:
                    continue

                wy = wx[j:r_y]
                wy.sort(key=lambda p: p[2])
                for k in range(len(wy) - max_pores):
                    if wy[k + max_pores][2] - wy[k][2] <= limit:
                        return False

