            math.floor(pt[0] / small_cell),
            math.floor(pt[1] / small_cell),
            math.floor(pt[2] / small_cell),
        )
        bucket = small_grid.setdefault(key, [])
        bucket.append(pt)
        if len(bucket) > max_pores:
            xs = [p[0] for p in bucket]
            ys = [p[1] for p in bucket]
            zs = [p[2] for p in bucket]
            if (
                max(xs) - min(xs) <= limit
                and max(ys) - min(ys) <= limit
                and max(zs) - min(zs) <= limit
            ):
                return False

    # Grid with cell size strictly larger than `limit` so every point within
    # `limit` along each axis lies in the same or immediately adjacent cell.
    cell_size = ref_size + 1e-3
    grid = {}
    for pt in pts:
        key = (
            math.floor(pt[0] / cell_size),
            math.floor(pt[1] / cell_size),
            math.floor(pt[2] / cell_size),
        )
        grid.setdefault(key, []).append(pt)

    # Any violating 5x5x5 box has a point with minimum x; anchor on each point
    # as the left x-face and sweep y and z within its candidate neighborhood.
    for (cx, cy, cz), cell_pts in grid.items():
        neighbor_pts = []
        for dx in (0, 1):
            for dy in (-1, 0, 1):
                for dz in (-1, 0, 1):
                    npts = grid.get((cx + dx, cy + dy, cz + dz))
                    if npts:
                        neighbor_pts.extend(npts)

        if len(neighbor_pts) <= max_pores:
            continue

        for px, py, pz in cell_pts:
            cand = [
                (qy, qz)
                for qx, qy, qz in neighbor_pts
                if 0.0 <= qx - px <= limit
                and abs(qy - py) <= limit
                and abs(qz - pz) <= limit
            ]
            if len(cand) <= max_pores:
                continue

            cand.sort()
            lo = 0
            for hi in range(len(cand)):
                y_hi = cand[hi][0]
                while y_hi - cand[lo][0] > limit:
                    lo += 1
                if hi - lo + 1 > max_pores:
                    zs = sorted(cand[i][1] for i in range(lo, hi + 1))
                    for k in range(len(zs) - max_pores):
                        if zs[k + max_pores] - zs[k] <= limit:
                            return False

    return True
